/* Data rangkuman 143 video — digenerate otomatis. */
window.RINGKASAN = [{"guid": "00eaf22a-b75a-4731-8b71-0ef784a86978", "judul": "Cara Membuat Kampanye LPWA dan Form", "library": "321776", "poin_penting": ["LPWA = iklan ke landing page lalu ke WhatsApp, Form = isi data lalu auto follow up ke WA", "Gunakan objective sales (bukan engagement) agar pixel bekerja", "Coba naik ke landing page setelah produk winning di CTWA dengan CPR di bawah 2000", "Mulai dari video basic ini sebelum ke strategi advance Test to Scale"], "ringkasan": "Video ini menjelaskan dua jenis kampanye lanjutan setelah CTWA: LPWA yang mengarahkan pembeli ke landing page lalu ke WhatsApp, dan kampanye Form yang mengumpulkan data lalu otomatis follow up via WhatsApp. Keduanya memakai objective sales agar pixel Meta bisa mencatat perilaku pengunjung. Cocok dicoba setelah produk terbukti laris di CTWA.", "langkah_praktis": ["Siapkan landing page produk yang sudah terbukti laris di CTWA (CPR di bawah 2000).", "Buka Ads Manager, buat campaign baru dengan objective Sales.", "Untuk LPWA: arahkan traffic ke landing page, pasang tombol WhatsApp yang jelas di halaman.", "Untuk Form: buat instant form, sambungkan agar data otomatis terkirim dan difollow up via WA.", "Jalankan dulu dengan budget kecil, bandingkan hasilnya dengan CTWA sebelum scale."]}, {"guid": "0391281d-37b8-4f43-ba4a-5dd70d5805a2", "judul": "Framework Test to Scale untuk Dropship", "library": "321776", "poin_penting": ["Mulai dari Testing Creative Phase: 1 campaign, budget 100rb, 3 produk, tiap produk 3-6 konten", "Kriteria winning: cost per klik di bawah 2000, budget terserap, ada penjualan", "Framework dirancang hemat budget dengan testing bertahap", "Setelah dapat pemenang baru lanjut ke fase scale"], "ringkasan": "Ini adalah kerangka kerja utama dropship dari testing sampai scale. Tahap awal fokus mencari produk dan konten iklan yang winning lewat satu campaign berisi tiga produk berbeda. Budget dibuat ramping agar testing tidak boros, dan hanya produk yang lolos kriteria yang dilanjutkan ke fase scale.", "langkah_praktis": ["Pilih 3 produk berbeda untuk di-testing dalam satu campaign.", "Buat 1 campaign dengan budget Rp100rb, tiap produk siapkan 3-6 variasi konten.", "Jalankan dan pantau: cost per klik, penyerapan budget, dan ada tidaknya penjualan.", "Tandai sebagai winning jika CPC di bawah 2000, budget terserap, dan ada order masuk.", "Matikan produk yang gagal, lanjutkan hanya yang winning ke fase scale."]}, {"guid": "10edaf87-3e80-41cf-85de-60f18659cbe2", "judul": "Cara Memilih Produk untuk Dropship", "library": "321776", "poin_penting": ["Ikuti tren: cek produk yang lagi ramai di Ad Library Meta atau TikTok", "Mulai tren: jual produk unik yang belum ada yang iklankan", "Pilih produk yang benar-benar menyelesaikan masalah pembeli", "Hindari produk tanpa nilai guna yang jelas karena rawan boncos"], "ringkasan": "Ada tiga pendekatan memilih produk dropship: mengikuti tren yang sedang ramai, menjadi yang pertama menjual produk unik, atau memilih berdasarkan manfaat nyata produk. Kuncinya adalah produk harus punya alasan kuat kenapa orang mau beli online, bukan sekadar ikut-ikutan jualan.", "langkah_praktis": ["Buka Meta Ad Library, cari produk sejenis dan lihat siapa saja yang sedang mengiklankannya.", "Cek TikTok untuk tren produk yang sedang ramai dibicarakan.", "Tuliskan masalah spesifik yang diselesaikan produk tersebut untuk pembeli.", "Coret produk yang tidak punya manfaat jelas — rawan boncos.", "Pilih 1-3 produk terbaik untuk masuk ke tahap testing iklan."]}, {"guid": "127aac9e-cc0f-4f72-914a-344298a6a527", "judul": "Cara Membuat Custom Audience", "library": "321776", "poin_penting": ["Custom audience = target orang yang sudah berinteraksi dengan bisnis kita", "Contoh: pengunjung website yang belum beli, bisa ditarget ulang", "Wajib pasang pixel dulu agar datanya terekam", "Dibuat lewat menu Audiences lalu pilih Create Audience"], "ringkasan": "Custom audience memungkinkan kita mengiklankan ulang ke orang yang sudah mengenal produk, misalnya pengunjung landing page yang belum checkout. Syaratnya pixel harus terpasang agar aktivitas mereka tercatat. Ini bahan dasar untuk retargeting dan lookalike audience.", "langkah_praktis": ["Pastikan pixel sudah terpasang di website/landing page agar data terekam.", "Buka Ads Manager, masuk ke menu Audiences.", "Klik Create Audience lalu pilih Custom Audience.", "Pilih sumbernya, misalnya pengunjung website 30 hari terakhir yang belum checkout.", "Beri nama yang jelas (contoh: Pengunjung LP - 30 hari) lalu simpan untuk dipakai retargeting."]}, {"guid": "136da79b-073d-4d24-9c0e-b56428d0f80a", "judul": "Cara Menghitung Laba Rugi Iklan", "library": "321776", "poin_penting": ["Hitung semua: HPP, biaya iklan, biaya COD, transaction fee, PPN 11%", "Dashboard terlihat winning belum tentu untung bersih", "Gunakan tabel laba rugi per transaksi agar melek angka", "PPN terasa besar saat spend iklan sudah di atas 500rb"], "ringkasan": "Video ini menekankan pentingnya menghitung untung rugi secara detail, bukan cuma melihat angka di dashboard. Banyak biaya tersembunyi seperti HPP ke gudang, biaya COD, fee transaksi, dan PPN yang bisa menggerus margin. Disediakan tabel Excel agar perhitungannya rapi.", "langkah_praktis": ["Catat HPP produk per transaksi dari supplier/gudang.", "Catat total biaya iklan yang keluar untuk mendapatkan transaksi tersebut.", "Tambahkan biaya tersembunyi: biaya COD, transaction fee, dan PPN 11%.", "Hitung: harga jual - (HPP + iklan + COD + fee + PPN) = untung bersih.", "Gunakan tabel per transaksi agar tidak terkecoh dashboard yang terlihat winning."]}, {"guid": "1e993814-2058-4677-9a6c-6160ff55ab7f", "judul": "Cara Setting Profanity Filter", "library": "321776", "poin_penting": ["Komentar negatif merusak kepercayaan calon pembeli", "Aktifkan fitur sembunyikan komentar mengandung kata kasar di pengaturan fanpage", "Tambahkan daftar kata terlarang sendiri untuk hasil maksimal", "Komentar yang disembunyikan tetap terlihat oleh penulisnya"], "ringkasan": "Komentar negatif dari pembeli kecewa (sering imbas ulah advertiser nakal) bisa menggagalkan penjualan. Solusinya adalah profanity filter: mengaktifkan penyembunyian otomatis kata kasar di fanpage plus memasukkan daftar kata sendiri, sehingga postingan iklan terlihat bersih dan terpercaya.", "langkah_praktis": ["Buka fanpage, masuk ke Pengaturan lalu cari bagian moderasi komentar.", "Aktifkan fitur sembunyikan komentar yang mengandung kata kasar.", "Tambahkan daftar kata terlarang sendiri sesuai pengalaman (nama kompetitor, kata menipu, dll).", "Simpan, lalu cek postingan iklan — komentar negatif kini tersembunyi otomatis."]}, {"guid": "1ea418c4-db62-4ef9-b1db-8b8068384901", "judul": "Strategi Laris Part 1: Memahami Market", "library": "321776", "poin_penting": ["Petakan demografi: usia, gender, domisili, status, jumlah anak", "Cari tahu minat dan akun sosmed yang mereka ikuti", "Ukur daya beli: masuk segmen middle atau middle up?", "Sesuaikan harga produk dengan kemampuan beli target market"], "ringkasan": "Sebelum beriklan, pahami dulu siapa target marketnya secara detail: demografi, minat, dan perilaku belanja. Harga produk harus masuk akal dengan daya beli mereka. Contohnya sepatu 600rb belum tentu laris kalau daya beli marketnya tidak sampai ke sana.", "langkah_praktis": ["Tulis profil target market: usia, gender, domisili, status, jumlah anak.", "Cari tahu minat mereka dan akun sosmed apa saja yang mereka ikuti.", "Tentukan segmen daya belinya: middle atau middle up.", "Sesuaikan harga produk agar masuk akal dengan kemampuan beli mereka.", "Pakai hasil pemetaan ini sebagai acuan targeting saat setting adset."]}, {"guid": "2dc7337a-7642-4e3c-af3d-c9aeee86a3b1", "judul": "Scale Out Interest Fase 1", "library": "321776", "poin_penting": ["Tujuan: cari interest yang paling cocok dengan konten winning", "Struktur: 1 campaign CBO 100rb, 4 adset dengan interest berbeda", "Pakai konten post ID yang sudah terbukti winning", "Lanjut ke fase 2 setelah dapat interest terbaik"], "ringkasan": "Setelah punya konten iklan yang winning, langkah berikutnya adalah mencari interest (minat target) yang paling cocok dengannya. Dibuat satu campaign berisi empat adset dengan interest berbeda-beda untuk diadu. Interest yang menang akan dipakai di fase scale berikutnya.", "langkah_praktis": ["Ambil post ID dari konten iklan yang sudah terbukti winning.", "Buat 1 campaign CBO dengan budget Rp100rb.", "Buat 4 adset, masing-masing dengan interest berbeda tapi konten yang sama.", "Jalankan dan bandingkan biaya per hasil tiap adset.", "Interest dengan hasil termurah dipakai untuk fase scale berikutnya."]}, {"guid": "306ea53b-0e7b-4dbe-abd8-cb86ca2bf888", "judul": "Simple Positioning: Keluar dari Perang Harga", "library": "321776", "poin_penting": ["Positioning = pembeda agar tidak adu murah", "Gunakan kata sakti 'khusus' untuk mengerucutkan niche", "Tonjolkan fitur atau manfaat yang belum diangkat kompetitor", "Contoh: sepatu biasa vs sepatu khusus pelari maraton"], "ringkasan": "Ketika semua penjual menawarkan hal yang sama, pembeli hanya membandingkan harga termurah. Solusinya adalah positioning: menonjolkan keunikan spesifik produk sehingga pembeli memilih berdasarkan kebutuhan, bukan harga. Contohnya pasta gigi yang dibedakan fungsinya atau hijab yang dispesifikkan jenisnya.", "langkah_praktis": ["Tulis 3 keunikan produkmu yang belum diangkat kompetitor.", "Pilih satu yang paling spesifik, lalu bungkus dengan kata 'khusus' (contoh: khusus pelari).", "Tonjolkan manfaat unik itu di headline dan konten iklan.", "Uji respon market: jika yang ditanya soal manfaat bukan harga, positioning berhasil."]}, {"guid": "3260fdf3-d60c-4610-88d2-d9b4eb9cdb2b", "judul": "Scale Out Broad Fase 2: Manual Bidding", "library": "321776", "poin_penting": ["Butuh data dulu: jalankan ASC 7 hari dan catat rata-rata CPR", "Bid mengikuti median hasil sebelumnya, jangan asal tebak", "Tanpa data, campaign bisa tidak nge-spend sama sekali", "Budget mulai 100rb dengan CBO"], "ringkasan": "Fase lanjutan scale out memakai manual bidding berdasarkan data nyata dari campaign sebelumnya. Nilai bid diambil dari rata-rata cost per result selama 7 hari. Tanpa data yang cukup, campaign berisiko tidak jalan karena tawaran tidak kompetitif di lelang.", "langkah_praktis": ["Jalankan campaign ASC broad selama 7 hari penuh terlebih dulu.", "Catat rata-rata cost per result (CPR) harian selama 7 hari itu.", "Buat campaign baru, pilih bid strategy manual/bid cap.", "Isi nilai bid mengikuti median CPR yang sudah dicatat — jangan asal tebak.", "Set budget Rp100rb dengan CBO, pantau apakah campaign nge-spend normal."]}, {"guid": "35f323cd-7f8d-423d-8071-30656f0720bc", "judul": "Cara Kerja Meta Ads dan Jenis Objective", "library": "321776", "poin_penting": ["Iklan tampil di Facebook, Instagram, dan WhatsApp", "Pilih objective sesuai tujuan: awareness, traffic, engagement, leads, sales", "Engagement murah tapi audiensnya suka interaksi, bukan beli", "Sales lebih mahal tapi audiensnya lebih siap beli"], "ringkasan": "Meta Ads bekerja berdasarkan objective yang kita pilih, dan tiap objective menjangkau tipe audiens berbeda. Kesalahan umum adalah salah pilih objective sehingga iklan murah tapi tidak menghasilkan penjualan. Pahami dulu tujuannya sebelum setting campaign.", "langkah_praktis": ["Tentukan dulu tujuan iklanmu: dikenal, diklik, atau langsung beli.", "Buka Ads Manager dan mulai buat campaign baru.", "Pilih objective yang sesuai: Sales jika targetnya transaksi.", "Hindari objective Engagement jika tujuan akhirmu penjualan.", "Lanjutkan setting adset dan ads seperti biasa."]}, {"guid": "384b20d1-7fe9-490e-b1a4-193280b821f5", "judul": "Prinsip One Week One Winning Product", "library": "321776", "poin_penting": ["Produk winning ada umurnya: bisa 2 minggu, bisa 6 bulan", "Saat 1 produk jalan, siapkan testing produk baru untuk minggu depan", "Keuntungan produk lama diputar untuk riset produk baru", "Berhenti riset hanya jika resource sudah tidak cukup"], "ringkasan": "Kunci keberlangsungan dropship adalah tidak bergantung pada satu produk saja. Setiap minggu harus ada satu produk baru yang di-testing, karena produk yang sekarang laris pasti akan menurun. Keuntungan digulung terus untuk riset sampai punya banyak produk winning yang jalan bersamaan.", "langkah_praktis": ["Tandai di kalender: tiap minggu ada jadwal riset produk baru.", "Sisihkan sebagian keuntungan produk lama khusus untuk budget testing.", "Jalankan testing produk baru sambil produk lama masih jalan.", "Catat produk mana yang winning agar bisa diulang polanya.", "Berhenti riset hanya jika waktu atau modal benar-benar habis."]}, {"guid": "3e3e1133-b308-4a1b-975e-d14b80e2c282", "judul": "Apa Itu Facebook Pixel dan Cara Membuatnya", "library": "321776", "poin_penting": ["Pixel = alat pencatat aktivitas pengunjung website", "Bisa tahu siapa yang view, klik tombol, isi form, checkout", "Dibuat di Business Settings lalu menu Data Set", "Beri nama pixel yang jelas sesuai brand"], "ringkasan": "Pixel adalah kode pelacak yang mencatat apa saja yang dilakukan pengunjung setelah klik iklan. Data ini penting untuk mengukur funnel dan membuat custom audience. Video ini menjelaskan cara membuatnya di Business Settings karena lokasinya sudah pindah ke menu Data Set.", "langkah_praktis": ["Buka Business Settings di Meta.", "Masuk ke menu Data Set (dulu bernama Pixel).", "Klik buat baru, beri nama pixel yang jelas sesuai brand-mu.", "Salin pixel ID-nya untuk dipakai saat install ke website."]}, {"guid": "3e423656-4467-48c1-ba77-5eab8fca9e90", "judul": "Analogi Sebar Brosur Pakai Ojek", "library": "321776", "poin_penting": ["Targeting Meta Ads seperti pesan ojek: tujuan, penerima, alamat jelas", "Brosur acak = buang-buang budget ke orang yang tidak tertarik", "Di Meta Ads semua terukur: view, klik, follow, komentar", "Bayar setelah iklan tersebar, bukan di depan"], "ringkasan": "Melalui analogi pesan ojek vs sebar brosur acak, video ini menjelaskan keunggulan targeting Meta Ads. Kita bisa menentukan siapa yang melihat iklan berdasarkan demografi, minat, dan perilaku, lalu mengukur hasilnya secara detail untuk keputusan berikutnya.", "langkah_praktis": ["Tuliskan siapa target iklanmu sejelas alamat ojek: usia, lokasi, minat.", "Jangan pasang iklan ke semua orang — itu seperti sebar brosur acak.", "Setelah iklan jalan, catat metriknya: view, klik, follow, komentar.", "Evaluasi: bagian mana yang bocor, lalu perbaiki sebelum tambah budget."]}, {"guid": "5418caac-ea45-48be-8baa-90d2d9f97af2", "judul": "Scale Out Interest Fase 2 (1-3-3)", "library": "321776", "poin_penting": ["Duplikat interest winning jadi 3 adset yang identik", "Tiap adset isi 3 konten iklan yang sama (struktur 1-3-3)", "Tujuannya 'boost algoritma' agar menang di lelang", "Jalankan 3 hari (jam 5 pagi-11 malam) lalu evaluasi"], "ringkasan": "Teknik scale dengan menduplikasi interest yang sudah winning menjadi tiga adset identik berisi konten yang sama. Pola ini diyakini membuat algoritma menganggap konten tersebut populer sehingga lebih sering ditampilkan. Dievaluasi tiap 3 hari untuk keputusan naik budget atau matikan.", "langkah_praktis": ["Pilih 1 interest yang sudah terbukti paling murah di fase sebelumnya.", "Duplikat menjadi 3 adset yang identik dalam 1 campaign.", "Isi tiap adset dengan 3 konten iklan yang sama (pola 1-3-3).", "Jalankan 3 hari, jam 5 pagi sampai 11 malam.", "Evaluasi: naikkan budget yang profit, matikan yang boncos."]}, {"guid": "62bba527-d95c-4e24-bfe0-668e4cbff704", "judul": "Kapan Waktu yang Tepat Scale Up dan Scale Out", "library": "321776", "poin_penting": ["Scale hanya jika campaign winning minimal 4-7 hari", "Scale up = naikkan budget campaign yang sudah ada", "Scale out = buat campaign baru dengan struktur berbeda", "Scale terlalu dini bikin biaya membengkak dan boncos"], "ringkasan": "Banyak pengiklan gagal karena scale terburu-buru padahal campaign belum stabil. Aturannya: pastikan performa bagus dan konsisten selama beberapa hari dulu. Scale up dilakukan dengan menaikkan budget, sedangkan scale out dengan membuat campaign baru.", "langkah_praktis": ["Pastikan campaign sudah winning dan stabil minimal 4-7 hari.", "Jika mau scale up: naikkan budget campaign yang sudah ada secara bertahap.", "Jika mau scale out: buat campaign baru dengan struktur berbeda (broad/interest/LLA).", "Jangan lakukan keduanya terburu-buru — scale yang terlalu dini bikin boncos."]}, {"guid": "6b905cc8-896e-4c87-9250-d0c4c6bc3d1f", "judul": "Memahami Struktur Campaign, Adset, dan Ads", "library": "321776", "poin_penting": ["Campaign = induk, tempat setting dasar dan objective", "Adset = level targeting: siapa yang dituju, budget per adset", "Ads = level konten: gambar, video, dan copywriting", "Pahami hierarki ini sebelum bahas materi teknis"], "ringkasan": "Struktur iklan Meta terdiri dari tiga level: campaign sebagai wadah utama, adset untuk pengaturan target audiens, dan ads untuk konten kreatifnya. Memahami hierarki ini adalah fondasi wajib agar tidak bingung saat masuk ke materi teknis berikutnya.", "langkah_praktis": ["Buat Campaign dulu: tentukan objective-nya (misal Sales).", "Di dalamnya buat Adset: atur siapa targetnya dan berapa budgetnya.", "Di dalam adset buat Ads: upload gambar/video dan tulis copywriting-nya.", "Ingat urutannya selalu: Campaign > Adset > Ads sebelum masuk materi teknis."]}, {"guid": "76f7e981-2710-4a85-b39b-a0ebaddfc0f5", "judul": "Cara Membuat Kampanye Retargeting", "library": "321776", "poin_penting": ["Target: orang yang sudah lihat iklan/kunjungi web tapi belum beli", "Wajib pakai konten BERBEDA (offer baru), jangan yang sama", "Struktur: 1 campaign CBO 50rb, audience custom gabungan", "Audiens kecil tapi sudah kenal produk, peluang closing besar"], "ringkasan": "Retargeting menyasar orang yang sudah berinteraksi tapi belum membeli. Kuncinya adalah konten harus berbeda dari iklan sebelumnya agar tidak membosankan — misalnya dengan offer baru seperti gratis ongkir atau bundling. Budgetnya kecil karena audiensnya terbatas.", "langkah_praktis": ["Buat custom audience berisi pengunjung web/penonton video yang belum beli.", "Buat 1 campaign CBO dengan budget Rp50rb khusus retargeting.", "Siapkan konten BERBEDA dari iklan awal — tambahkan offer baru (gratis ongkir/bundling).", "Jalankan dan pantau closing rate-nya yang biasanya lebih tinggi."]}, {"guid": "7e1400ba-225f-4387-a9e9-f335845bb0ab", "judul": "Menyusun The Gameplan Sebelum Beriklan", "library": "321776", "poin_penting": ["Tentukan KPI di depan sebelum campaign jalan", "Gameplan berisi: kapan lanjut, kapan evaluasi, kapan berhenti", "Fokuskan budget iklan ke produk penetrasi saja", "Produk lanjutan dijual tanpa iklan via follow up"], "ringkasan": "Gameplan adalah rencana angka yang dibuat sebelum beriklan agar keputusan tidak berdasarkan perasaan. Ditentukan dulu target biayanya, lalu aturan mainnya: kondisi seperti apa yang dilanjutkan dan kapan harus berhenti. Iklan difokuskan ke produk penetrasi, sisanya mengandalkan follow up.", "langkah_praktis": ["Tulis target angka di atas kertas: CPR maksimal yang masih untung.", "Buat aturan main: lanjut jika di bawah KPI, evaluasi jika mepet, berhenti jika jebol.", "Alokasikan budget iklan hanya untuk produk penetrasi (produk murah pintu masuk).", "Siapkan skrip follow up untuk menjual produk lanjutan tanpa iklan."]}, {"guid": "8301b19a-54c7-4835-a0e6-0f05904cdd6b", "judul": "Memahami Manual Bidding dan Bid Cap", "library": "321776", "poin_penting": ["Bid cap = batas maksimal tawaran lelang yang kita set", "Facebook akan cari audiens dengan biaya di bawah batas itu", "Setting di campaign bid strategy, nilai bid di adset", "Cocok untuk menjaga biaya tetap di bawah KPI"], "ringkasan": "Berbeda dengan bidding otomatis, manual bidding memberi kita kendali atas batas tawaran lelang. Dengan bid cap, misalnya KPI 25rb, maka sistem akan berusaha mendapatkan hasil di bawah angka itu. Teknik ini berguna saat scale agar biaya tidak melonjak.", "langkah_praktis": ["Tentukan dulu KPI biaya per hasil yang masih menguntungkanmu.", "Buka setting campaign, pilih bid strategy lalu pilih Bid Cap.", "Masuk ke level adset, isi nilai bid sesuai KPI yang sudah ditentukan.", "Jalankan dan pastikan biaya per hasil tidak melewati batas yang diset."]}, {"guid": "830bfb62-59ca-48cf-9867-ad08546530c8", "judul": "Cara Kerja Algoritma Meta Ads", "library": "321776", "poin_penting": ["Iklan disebar sesuai minat dari aktivitas sosmed", "Riwayat belanja menentukan iklan seharga yang pernah dibeli", "Meta bisa cari orang mirip pelanggan kita (lookalike)", "Ujungnya tetap manusia: konten harus menarik perhatian"], "ringkasan": "Algoritma Meta mempelajari tiga hal: apa yang kita sukai di sosmed, berapa nilai belanja kita, dan siapa yang mirip dengan pelanggan sebuah brand. Pemahaman ini membantu kita menyusun targeting dan konten yang tepat sasaran, bukan sekadar asal pasang iklan.", "langkah_praktis": ["Pelajari minat audiens dari aktivitas sosmed yang relevan dengan produkmu.", "Perhatikan kisaran harga yang biasa mereka beli online.", "Manfaatkan lookalike audience untuk menjangkau orang yang mirip pelangganmu.", "Fokuskan energi ke konten yang menarik perhatian — algoritma hanya penyalur."]}, {"guid": "88c67858-1e11-464e-a4f5-0fe13acd9b5f", "judul": "Orthodox Matrix: 4 Metrik Wajib", "library": "321776", "poin_penting": ["CTR Link Click standar 1%: ukur daya tarik konten", "OCLP standar 70%: ukur kecepatan landing page", "LP Convert standar 25%: ukur isi landing page dan offer", "CS Convert standar 30%: ukur kemampuan closing CS"], "ringkasan": "Ada empat metrik baku untuk membaca performa iklan dari hulu ke hilir: seberapa menarik kontennya, seberapa cepat landing page-nya, seberapa meyakinkan isi halamannya, dan seberapa jago CS menutup penjualan. Tiap metrik menunjuk bagian mana yang bermasalah saat iklan boncos.", "langkah_praktis": ["Cek CTR Link Click di dashboard — standar sehatnya 1%. Di bawah itu, kontennya yang bermasalah.", "Hitung OCLP (landing page views / link clicks) — standarnya 70%. Rendah berarti halaman lambat.", "Cek LP Convert — standarnya 25%. Rendah berarti isi halaman atau offer-nya kurang meyakinkan.", "Cek CS Convert — standarnya 30%. Rendah berarti tim closing perlu dibenahi."]}, {"guid": "8ecdd794-11e3-43c4-9191-b0f23b45d9ac", "judul": "Optimasi Kolom Komentar Iklan", "library": "321776", "poin_penting": ["Calon pembeli membaca komentar sebelum memutuskan beli", "Tampilkan testimoni asli di komentar teratas postingan iklan", "Di Facebook bisa pakai 'post with comment' bergambar", "Terbukti menurunkan biaya per hasil karena trust naik di depan"], "ringkasan": "Sebelum klik iklan, orang biasanya mengintip kolom komentar untuk memastikan produknya asli. Triknya adalah menaruh testimoni (teks maupun gambar) di komentar teratas agar keraguan hilang sejak awal. Cara ini terbukti menurunkan biaya iklan karena konversi naik.", "langkah_praktis": ["Kumpulkan testimoni asli pembeli (chat screenshot atau foto).", "Buka postingan iklan, sematkan testimoni terbaik sebagai komentar teratas.", "Di Facebook, manfaatkan fitur post with comment bergambar agar testimoni menonjol.", "Pantau biaya per hasil — biasanya turun karena trust naik sejak awal."]}, {"guid": "9ae4508e-d423-472a-b596-8b4c6432b79f", "judul": "Setting Rule Otomatis Pengaman Budget", "library": "321776", "poin_penting": ["Rule mematikan otomatis campaign yang boncos", "Contoh: spend 30rb tanpa lead = mati sendiri", "Beri 'nafas' bertahap: makin banyak lead, makin longgar batasnya", "Tidak perlu mantengin laptop seharian"], "ringkasan": "Rule adalah fitur otomatisasi yang mematikan campaign berdasar aturan yang kita buat, misalnya campaign dimatikan jika sudah keluar budget tertentu tanpa menghasilkan lead. Aturannya bisa berlapis: semakin banyak lead masuk, semakin besar toleransi budgetnya. Ini pengaman agar tidak boncos saat ditinggal.", "langkah_praktis": ["Buka Ads Manager, masuk ke menu Rules (Automated Rules).", "Buat rule pertama: jika spend Rp30rb tanpa lead, matikan campaign otomatis.", "Buat rule berlapis: makin banyak lead masuk, makin longgar batas toleransinya.", "Aktifkan rule dan biarkan sistem menjaga budget saat kamu tidak mantengin laptop."]}, {"guid": "9f511981-761e-4fd8-8697-530e17adc96c", "judul": "Scale Out Broad Fase 1 dengan ASC", "library": "321776", "poin_penting": ["Gunakan Advantage Shopping Campaign dengan broad audience", "Budget 100rb, konten dari post ID yang winning", "Setting lokasi di ad account audience control", "Jalan 2-3 hari, kalau bagus naikkan budget 20%"], "ringkasan": "Fase scale pertama memakai ASC (Advantage Shopping Campaign) dengan target luas tanpa interest. Kontennya diambil dari post ID yang sudah terbukti winning di fase testing. Aturannya sederhana: jalankan beberapa hari, jika performa bagus naikkan budget bertahap 20%.", "langkah_praktis": ["Buat Advantage Shopping Campaign (ASC) baru dengan audience broad.", "Set budget Rp100rb, pakai konten dari post ID yang sudah winning.", "Atur lokasi di ad account audience control.", "Jalankan 2-3 hari dan pantau performanya.", "Jika bagus, naikkan budget 20% secara bertahap."]}, {"guid": "a5aa4760-419a-4bc7-b915-519f19828bfa", "judul": "Product Fit Meta Ads Part 1", "library": "321776", "poin_penting": ["Tidak semua produk cocok diiklankan di Meta Ads", "Syarat: marketnya ada dan besar di Facebook/Instagram", "Targetkan pembeli sebenarnya (contoh: sepatu anak → target orang tuanya)", "Produk harus punya manfaat yang jelas"], "ringkasan": "Sebelum beriklan, pastikan produknya memang cocok untuk Meta Ads. Syarat utamanya adalah calon pembelinya aktif di Facebook atau Instagram dan jumlahnya cukup besar. Kadang targetnya bukan pemakai langsung, misalnya produk anak-anak yang dibeli orang tuanya.", "langkah_praktis": ["Cek apakah calon pembeli produkmu aktif di Facebook/Instagram.", "Pastikan jumlah mereka cukup besar, bukan niche yang terlalu sempit.", "Identifikasi siapa pembeli sebenarnya (contoh: produk anak → target orang tua).", "Pastikan produk punya manfaat yang jelas sebelum keluar budget iklan."]}, {"guid": "a9990d53-84b3-4348-8cfc-c5450028b14e", "judul": "Cara Setting Adset", "library": "321776", "poin_penting": ["Beri nama adset yang jelas: produk + targetingnya", "Pilih conversion location: website, messaging, atau calls", "Untuk dropship ke WA gunakan messaging apps dengan objective sales", "Atur agar budget dimaksimalkan untuk konversi"], "ringkasan": "Adset adalah level tempat kita mengatur siapa yang dituju iklan. Video ini memandu settingnya langkah demi langkah: penamaan, pilihan tujuan konversi (website atau chat WhatsApp), dan optimasi budget agar fokus mendapatkan hasil.", "langkah_praktis": ["Beri nama adset yang jelas: nama produk + jenis targetingnya.", "Pilih conversion location: website, messaging, atau calls.", "Untuk dropship ke WhatsApp: pilih messaging apps dengan objective sales.", "Atur budget agar sistem memaksimalkan peluang konversi."]}, {"guid": "b0ed39e1-addc-421f-aa0f-4eb9603a48f6", "judul": "Mindset Facebook dan Instagram Ads", "library": "321776", "poin_penting": ["Meta Ads hanyalah alat, bukan jaminan laris", "Yang menentukan: produk, value, dan konten iklan", "Manusia yang melihat iklan, pahami kebutuhan mereka", "Benahi dulu produk dan konten sebelum utak-atik settingan"], "ringkasan": "Kesalahan terbesar pemula adalah mengira settingan iklan yang menentukan laris tidaknya. Padahal Meta Ads cuma alat penyalur; yang dibenahi justru produknya, penawarannya, dan kontennya. Sepanjang hari orang dibombardir iklan, hanya konten yang stand out yang dilirik.", "langkah_praktis": ["Evaluasi dulu produkmu: apakah memang dibutuhkan market?", "Perbaiki value dan penawarannya sebelum menyentuh settingan iklan.", "Buat konten yang stand out di tengah banjir iklan harian.", "Baru setelah itu utak-atik targeting dan budget di Ads Manager."]}, {"guid": "b429b8a0-14c9-41fd-8bbc-0df462b5366f", "judul": "Cara Install Pixel Manual ke Website", "library": "321776", "poin_penting": ["Copy base code pixel dari Events Manager", "Paste di header atau footer website builder (WordPress, Weebly)", "Cek dengan Meta Pixel Helper di Chrome", "Hindari double install (header + footer) agar tidak error"], "ringkasan": "Untuk website builder yang tidak mendukung install otomatis, kode pixel harus dipasang manual. Caranya: ambil base code dari Events Manager, tempel di bagian header atau footer, lalu verifikasi dengan ekstensi Meta Pixel Helper. Event bisa diubah misalnya dari page view menjadi add to cart.", "langkah_praktis": ["Buka Events Manager, salin base code pixel-mu.", "Tempel kode tersebut di bagian header atau footer website (WordPress/Weebly).", "Install ekstensi Meta Pixel Helper di Chrome.", "Buka websitemu dan pastikan helper menunjukkan pixel aktif tanpa error.", "Jangan pasang di header sekaligus footer — pilih salah satu agar tidak double."]}, {"guid": "b4db4032-7b14-45be-be92-94c2a9c4b0db", "judul": "Mindset: Meta Ads Bukan Judi", "library": "321776", "poin_penting": ["Iklan menghasilkan data, judi tidak bisa dianalisa", "Saat boncos, cek datanya: CTR, landing page, atau offer", "Setiap campaign bisa didesain: usia, gender, lokasi, minat", "Monitor dan evaluasi rutin, bukan pasang lalu pasrah"], "ringkasan": "Banyak pemula memperlakukan iklan seperti judi: pasang budget lalu berharap untung. Padahal setiap iklan menghasilkan data yang bisa dibaca untuk tahu bagian mana yang salah. Dengan desain campaign yang tepat plus monitoring rutin, keputusan iklan jadi berbasis data bukan tebakan.", "langkah_praktis": ["Sebelum pasang iklan, tulis desain campaign: target usia, gender, lokasi, minat.", "Jalankan campaign lalu catat datanya setiap hari.", "Saat boncos, bedah datanya: CTR rendah = konten, convert rendah = landing page/offer.", "Perbaiki bagian yang bermasalah, jangan asal ganti settingan.", "Ulangi siklus monitor-evaluasi-perbaiki sampai profit stabil."]}, {"guid": "b968c4a7-b32d-470c-8843-6febceff0928", "judul": "Cara Setting Campaign yang Benar", "library": "321776", "poin_penting": ["Pilih objective sales untuk fase testing", "Beri nama terstruktur: tanggal + produk + jenis budget", "Budget testing 100rb dengan Advantage Campaign Budget", "Bid strategy high volume saat masih testing"], "ringkasan": "Video ini memandu pembuatan campaign dari nol: memilih objective yang sesuai tujuan, memberi nama yang rapi agar mudah dilacak saat campaign sudah banyak, mengatur budget, dan memilih strategi bidding yang tepat untuk fase testing.", "langkah_praktis": ["Buat campaign baru, pilih objective Sales untuk fase testing.", "Beri nama terstruktur: tanggal-produk-jenis budget (contoh: 20261019-sepatu-CBO).", "Set budget Rp100rb dengan Advantage Campaign Budget aktif.", "Pilih bid strategy Highest Volume.", "Simpan dan lanjutkan ke setting adset."]}, {"guid": "c6cef34e-f785-4899-b641-a83d97b23d39", "judul": "Mengenal Fitur Dashboard Meta Ads", "library": "321776", "poin_penting": ["Kenali semua tombol sebelum praktek agar tidak bingung", "Satu akun personal bisa membawahi banyak BM", "Tiap BM bisa punya beberapa akun iklan", "Jangan beriklan di akun personal, pakai BM agar aman"], "ringkasan": "Tour lengkap mengenal dashboard Meta Ads: dari logo, kumpulan akun BM, sampai daftar aset bisnis. Penting dipahami struktur akunnya — akun personal yang menaungi BM — karena beriklan di akun personal berisiko membuat semua akses terkunci saat kena restrict.", "langkah_praktis": ["Buka dashboard Meta Ads dan kenali tiap tombol serta menunya satu per satu.", "Pahami struktur: akun personal menaungi BM, BM menaungi akun-akun iklan.", "Buat dan gunakan Business Manager untuk beriklan.", "Jangan pernah beriklan langsung dari akun personal — rawan terkunci total."]}, {"guid": "d0664c76-1839-41c1-9eec-8f1939c8c05b", "judul": "Maksimalkan Fitur WhatsApp Business", "library": "321776", "poin_penting": ["Simpan template balasan cepat, panggil dengan tombol /", "Beri label pada chat: sudah beli, tanya-tanya, sudah kirim", "Lengkapi profil: alamat, jam buka, katalog, banner", "Foto profil pakai wajah asli agar terlihat seperti CS beneran"], "ringkasan": "WhatsApp Business punya fitur yang tidak ada di WA biasa dan sangat membantu saat banjir chat dari iklan. Template balasan cepat menghemat waktu mengetik, label memudahkan follow up, dan profil yang lengkap membuat toko terlihat profesional dan meyakinkan.", "langkah_praktis": ["Buka WhatsApp Business, buat template balasan cepat untuk pertanyaan yang sering masuk.", "Panggil template dengan mengetik garis miring (/) saat membalas chat.", "Beri label pada tiap chat: sudah beli, tanya-tanya, sudah kirim.", "Lengkapi profil: alamat, jam buka, katalog produk, dan banner.", "Ganti foto profil dengan foto wajah asli agar terlihat seperti CS beneran."]}, {"guid": "d0837602-f08c-4fa8-bc63-19f576a91fd0", "judul": "Cara Membuat Akun BM dan Fanpage", "library": "321776", "poin_penting": ["Buat fanpage dulu dengan nama yang general", "Jangan pakai akun Facebook baru, rawan kena restrict", "Ikuti urutan step-by-step karena tampilan sering berubah", "Contoh nama: toko berkah untuk produk fisik"], "ringkasan": "Panduan langkah demi langkah membuat fanpage dan Business Manager sebagai fondasi beriklan. Ditekankan untuk memakai akun Facebook yang sudah lama agar tidak dianggap spam, dan memilih nama halaman yang umum agar fleksibel untuk banyak produk.", "langkah_praktis": ["Buat fanpage baru dengan nama yang general (contoh: toko berkah).", "Gunakan akun Facebook yang sudah lama, jangan akun baru.", "Ikuti urutan pembuatan step by step sesuai tampilan terbaru.", "Setelah fanpage jadi, buat Business Manager dan hubungkan keduanya."]}, {"guid": "d78f3680-8286-4d63-92d0-48c8f221b4f7", "judul": "Product Fit Part 2: Produk Penetrasi", "library": "321776", "poin_penting": ["Produk penetrasi = produk murah untuk akuisisi customer baru", "Ciri: murah, tersegmentasi, banyak peminat, ready stock", "Setelah beli, follow up tawarkan produk lain yang lebih mahal", "Wajib berkualitas bagus agar customer mau repeat order"], "ringkasan": "Strategi brand owner: jual dulu produk murah sebagai 'pintu masuk' untuk mendapatkan data customer, lalu tawarkan produk-produk lain lewat follow up tanpa perlu iklan lagi. Kuncinya produk penetrasi harus berkualitas agar customer percaya dan mau beli lagi.", "langkah_praktis": ["Pilih produk murah, tersegmentasi, dan banyak peminat sebagai produk penetrasi.", "Pastikan produk ready stock dan kualitasnya bagus.", "Iklankan produk ini sebagai pintu masuk untuk mendapatkan data customer.", "Setelah mereka beli, follow up via WA untuk menawarkan produk yang lebih mahal."]}, {"guid": "d7af33da-65f2-4d4b-868c-93d21d9b49d8", "judul": "Beriklan untuk Bisnis Offline", "library": "321776", "poin_penting": ["Targetkan wilayah sekitar lokasi bisnis saja", "Pilih objective sesuai tujuan: awareness atau chat order", "Bisa juga untuk rekrut reseller di daerah lain", "Cara mainnya beda dengan bisnis online"], "ringkasan": "Pemilik usaha offline (misalnya toko bangunan) juga bisa beriklan di Meta Ads dengan pendekatan berbeda: targeting difokuskan ke area sekitar toko. Tujuannya bisa untuk dikenal warga sekitar, mendatangkan pembeli ke toko, atau menerima pesanan via WhatsApp.", "langkah_praktis": ["Tentukan radius target: hanya wilayah sekitar lokasi tokomu.", "Pilih objective sesuai tujuan: awareness untuk dikenal, atau chat untuk terima order.", "Buat konten yang menonjolkan lokasi dan kemudahan datang ke toko.", "Pertimbangkan juga memakai iklan untuk merekrut reseller di daerah lain."]}, {"guid": "db74e159-a6ac-4fd4-9f3d-6ab6d6101ec6", "judul": "Praktek Setting Orthodox Matrix di Dashboard", "library": "321776", "poin_penting": ["Tambahkan kolom CTR Link Click lewat Customize Column", "Buat custom metric OCLP: landing page views dibagi link clicks", "Susun urutan kolom: impresi, CTR, OCLP, dst", "Setting sekali, dipakai untuk semua campaign"], "ringkasan": "Lanjutan dari teori Orthodox Matrix: praktek langsung menambahkan metrik-metrik kunci ke dalam dashboard Meta Ads. Termasuk cara membuat custom metric OCLP dengan rumus sederhana agar kecepatan landing page bisa dipantau dari dashboard.", "langkah_praktis": ["Buka dashboard Ads Manager, klik Customize Columns.", "Tambahkan kolom CTR Link Click ke tampilan.", "Buat custom metric OCLP dengan rumus: landing page views dibagi link clicks.", "Susun urutan kolom: impresi, CTR, OCLP, lalu metrik konversi.", "Simpan sebagai tampilan default agar dipakai di semua campaign."]}, {"guid": "e1e9f1c2-2b2d-4ea9-89b4-a0d0c0038ecb", "judul": "Scale Out dengan Lookalike Audience 1-4%", "library": "321776", "poin_penting": ["Butuh custom audience minimal 1000 orang (CA1000++)", "Struktur: 1 campaign, 4 adset (LLA 1%, 1-2%, 2-3%, 3-4%)", "Wajib pakai konten post ID yang winning", "Jalan 3 hari (jam 5 pagi-11 malam) lalu evaluasi"], "ringkasan": "Setelah iklan jalan beberapa minggu dan terkumpul data pengunjung, buat lookalike audience untuk menjangkau orang-orang yang mirip dengan mereka. Dibagi dalam empat rentang kemiripan agar bisa dibandingkan mana yang paling murah biayanya.", "langkah_praktis": ["Pastikan custom audience-mu sudah berisi minimal 1000 orang.", "Buat 1 campaign dengan 4 adset: LLA 1%, 1-2%, 2-3%, dan 3-4%.", "Isi semua adset dengan konten dari post ID yang sudah winning.", "Jalankan 3 hari (jam 5 pagi - 11 malam).", "Bandingkan biaya per hasil, pertahankan rentang yang paling murah."]}, {"guid": "e3b49ece-ba07-48c2-b285-812dde55d82c", "judul": "Strategi Laris Part 2: Value Produk", "library": "321776", "poin_penting": ["Kenali manfaat utama produkmu", "Ciptakan manfaat tambahan yang tidak dimiliki kompetitor", "Contoh: Nike dengan teknologi dry system dan air-max", "Value yang kuat membuat orang rela bayar lebih"], "ringkasan": "Selain memahami market, brand owner harus paham betul value produknya. Tiap produk punya manfaat utama, tapi yang membedakan adalah manfaat tambahan — fitur unik yang tidak ditawarkan kompetitor. Inilah yang membuat produk laris meski harganya lebih mahal.", "langkah_praktis": ["Tulis manfaat utama produkmu dalam satu kalimat.", "Cari satu manfaat tambahan yang tidak dimiliki kompetitor.", "Jadikan manfaat tambahan itu headline di konten iklanmu.", "Uji: jika pembeli memilihmu bukan karena termurah, value-mu berhasil."]}, {"guid": "e51efbff-6ec7-4de1-9673-77634630ef09", "judul": "Digital Marketing Framework untuk Brand", "library": "321776", "poin_penting": ["Analogi: digital marketing = mengetuk lebih banyak pintu", "Jangkauan digital jauh lebih luas dari cara offline", "Tidak semua yang diketuk akan beli, itu wajar", "Framework ini terbukti dipakai banyak brand owner"], "ringkasan": "Melalui analogi mengetuk pintu dari rumah ke rumah, video ini menjelaskan keunggulan digital marketing: dengan usaha yang sama kita bisa menjangkau jauh lebih banyak calon pembeli. Framework ini menjadi panduan brand owner membesarkan omset lewat jalur digital.", "langkah_praktis": ["Pahami bahwa digital menjangkau jauh lebih banyak orang daripada cara offline.", "Mulai bangun kehadiran digital: sosmed, iklan, atau marketplace.", "Terima bahwa tidak semua yang melihat akan beli — itu wajar.", "Ikuti framework-nya bertahap: traffic dulu, baru optimasi konversi."]}, {"guid": "eb506a70-2bf8-43b1-8973-9ac66bdae49f", "judul": "Kenapa Akun Iklan Kena Ban dan Solusinya", "library": "321776", "poin_penting": ["Penyebab utama: akun baru langsung digas beriklan", "Facebook menganggap akun tanpa aktivitas sebagai spam", "Solusi: warming up dengan aktivitas natural dulu", "Akun whitelist lebih aman dari masalah ini"], "ringkasan": "Hampir semua pengiklan pernah mengalami akun kena restrict atau ban. Penyebab paling umum adalah akun baru yang langsung dipakai iklan tanpa aktivitas wajar seperti like dan komen. Solusinya adalah pemanasan akun terlebih dahulu, atau memakai akun whitelist.", "langkah_praktis": ["Jangan langsung pasang iklan di akun yang baru dibuat.", "Lakukan warming up: like, komen, dan aktivitas natural beberapa hari.", "Baru setelah itu mulai pasang iklan dengan budget kecil.", "Alternatif yang lebih aman: daftar dan pakai akun whitelist."]}, {"guid": "f21be672-fc87-4a74-bd1e-e05a97f4f220", "judul": "Cara Daftar Akun Whitelist Meta Ads", "library": "321776", "poin_penting": ["Daftar via melangkah.id dengan ID BM yang sudah siap", "Bebas PPN 11% sehingga biaya iklan lebih murah", "Ada tim support hampir 24 jam saat ada kendala", "Bisa request akun backup jika akun utama kena ban permanen"], "ringkasan": "Akun whitelist adalah akun iklan khusus dengan banyak kelebihan dibanding akun personal: bebas PPN, ada dukungan teknis, dan bisa dapat pengganti jika akun bermasalah. Video ini menjelaskan syarat dan cara registrasinya langkah demi langkah.", "langkah_praktis": ["Siapkan ID Business Manager yang sudah jadi.", "Buka situs pendaftaran (melangkah.id) dan isi formulir dengan ID BM tersebut.", "Tunggu proses verifikasi sampai akun whitelist aktif.", "Manfaatkan kelebihannya: bebas PPN 11% dan ada tim support.", "Jika akun utama kena ban permanen, request akun backup ke tim support."]}, {"guid": "f6d80043-bcaa-4dce-9bb0-f685d0952fd8", "judul": "Mindset Dropshipper yang Benar", "library": "321776", "poin_penting": ["Fokus ke produk: kalau tidak laku, ganti produknya", "Jangan buang waktu bangun followers untuk produk dropship", "Prinsip hit and run: jual, untung, pindah produk", "Siap ganti produk kapan saja karena tren berubah cepat"], "ringkasan": "Mindset dropshipper bertolak belakang dengan brand owner: tidak perlu membangun brand, fokusnya murni jualan dan cuan. Kalau produk sudah tidak winning — misalnya pasar sudah jenuh atau harga di marketplace lebih murah — langsung ganti, jangan dipaksakan.", "langkah_praktis": ["Fokuskan energimu ke mencari produk yang laku, bukan membangun followers.", "Jika produk tidak winning (pasar jenuh/harga kalah), segera ganti.", "Terapkan prinsip hit and run: jual, untung, pindah ke produk berikutnya.", "Jangan baper dengan satu produk — tren berubah cepat."]}, {"guid": "fc607c1e-dc8c-4efd-914e-e347357d0212", "judul": "Perbedaan Dropship dan Affiliate", "library": "321776", "poin_penting": ["Affiliate = dapat komisi dari link, andalkan konten organik", "Dropship = tentukan margin sendiri, andalkan iklan berbayar", "Affiliate: pembeli checkout langsung ke toko pemilik produk", "Dropship: pembeli bayar ke kita, kita teruskan ke supplier"], "ringkasan": "Keduanya sama-sama menjual produk orang lain, tapi cara mainnya beda. Affiliate mengandalkan konten organik yang diposting puluhan kali sehari untuk mengejar komisi. Dropship menentukan margin sendiri dan mengandalkan iklan berbayar, dengan alur pembeli membayar ke toko kita dulu.", "langkah_praktis": ["Tentukan dulu modelmu: affiliate (konten organik) atau dropship (iklan berbayar).", "Jika affiliate: siapkan posting konten puluhan kali sehari untuk kejar komisi.", "Jika dropship: siapkan budget iklan dan tentukan marginmu sendiri.", "Pahami alurnya: affiliate = checkout ke toko pemilik, dropship = bayar ke kamu dulu.", "Eksekusi konsisten sesuai model yang dipilih."]}, {"guid": "0bd1011a-581f-4203-8ef8-b9fb3336c85c", "judul": "Pengenalan Modul Ads Content", "library": "321766", "poin_penting": ["Konten iklan diperlakukan berbeda dari konten organik", "Tujuan akhir: jadi kreator yang bisa monetisasi (endorse, adsense, produk digital)", "Materi diklaim sebagai ilmu yang disimpan 2-3 tahun dan baru dibagikan"], "ringkasan": "Video pembuka modul Ads Content untuk para kreator. Materi ini membedakan cara membuat konten untuk iklan dengan konten organik biasa, karena perlakuannya berbeda. Tujuannya agar peserta bisa menjadi kreator yang menghasilkan lewat endorse, adsense, atau jualan produk digital sendiri.", "langkah_praktis": ["Pisahkan mindset: konten iklan perlakuannya beda dengan konten organik biasa", "Tentukan tujuanmu: mau dapat endorse, adsense, atau jual produk digital sendiri", "Siapkan 1 produk atau jasa yang mau dipromosikan lewat iklan", "Ikuti urutan materi modul ini dari awal sampai akhir, jangan loncat", "Catat 3 ide konten iklan pertama yang mau kamu buat setelah modul selesai"]}, {"guid": "1402eb2b-e2ba-4694-a881-11b4dd3ccae5", "judul": "Logika vs Pikiran Bawah Sadar Pembeli", "library": "321766", "poin_penting": ["95% keputusan membeli didorong pikiran bawah sadar, bukan logika", "Beli karena 'pengen' = emosi dominan; beli karena 'butuh' = logika dominan", "Targetkan emosi/perasaan dalam materi pemasaran", "Pengalaman buruk (ditipu, barang tak dikirim) membentuk trust issue yang harus diatasi"], "ringkasan": "Orang membeli lebih banyak karena dorongan pikiran bawah sadar (emosi) daripada logika — disebut-sebut 95% keputusan beli bersifat bawah sadar menurut studi Harvard. Karena itu pemasaran paling efektif menyentuh emosi, bukan sekadar adu argumen logis. Pengalaman buruk belanja online di masa lalu menumpuk jadi trust issue di memori bawah sadar calon pembeli.", "langkah_praktis": ["Tulis 3 emosi yang dirasakan target pembelimu (misal: takut, malu, pengen)", "Ambil 1 kalimat logis di iklanmu, ubah jadi kalimat yang menyentuh emosi", "Cari 3 pengalaman buruk umum pembeli online di niche-mu, siapkan kalimat penenangnya", "Uji iklanmu: baca ulang — apakah menyentuh perasaan atau cuma adu fakta?", "Perbaiki headline agar menyentuh emosi pembeli, bukan sekadar info produk"]}, {"guid": "1907cfcd-e46e-4a13-a59e-a7eb622d865a", "judul": "Kesan Pertama via WhatsApp", "library": "321766", "poin_penting": ["Kesan pertama di WA: foto profil, nama, kecepatan balas, kepedulian jawaban", "Hindari foto profil logo/gambar produk yang generik seperti kebanyakan toko", "Pakai foto orang asli agar terlihat personal dan membedakan", "Jawaban singkat seperti robot ('oke', 'ya') membuat calon pembeli ilfeel"], "ringkasan": "Saat calon pembeli pertama kali menghubungi via WhatsApp, mereka belum kenal dan belum percaya — kesan pertama ditentukan oleh foto profil, nama WA, kecepatan membalas, dan kepedulian dalam jawaban. Foto profil berupa logo toko atau gambar produk dianggap kurang membedakan karena semua penjual memakai gaya yang sama. Disarankan memakai foto orang asli agar terlihat personal dan beda dari kompetitor.", "langkah_praktis": ["Ganti foto profil WA bisnismu dengan foto orang asli, bukan logo atau gambar produk", "Pakai nama WA yang jelas dan personal, bukan sekadar nama toko", "Balas setiap chat maksimal dalam 5 menit selama jam kerja", "Latih jawaban: jangan cuma balas 'oke' atau 'ya', tulis kalimat peduli yang lengkap", "Minta 2 teman chat ke WA bisnismu dan tanya kesan pertama mereka"]}, {"guid": "190e679d-16e7-4761-9fe7-e828b7ebb3e8", "judul": "Winning Formula: Fokus Esensi Bisnis", "library": "321766", "poin_penting": ["Pahami target market dulu sebelum beriklan (siapa, di platform mana)", "Konten adalah gerbang utama penentu iklan — cari hook/angle yang tepat", "Tiru pola konten yang lagi tren dan terbukti di TikTok Creative Center", "Brand owner wajib terus testing dan produksi konten agar penjualan tidak turun"], "ringkasan": "Formula dasar agar produk bisa laku: pahami dulu target market sebelum beriklan — tidak semua orang adalah target market, dan iklan harus ditujukan ke orang yang tepat di platform yang tepat. Konten adalah penentu utama keberhasilan iklan; temukan hook atau angle yang tepat agar konten meledak. Contoh praktiknya memakai pola konten yang sedang tren dan terbukti bagus di TikTok untuk dipasang di Facebook/Instagram.", "langkah_praktis": ["Tulis profil target marketmu: usia, gender, dan platform yang mereka pakai", "Tentukan 1 platform utama untuk beriklan sesuai target market tersebut", "Buka TikTok Creative Center, cari 3 konten yang lagi tren di niche produkmu", "Tiru pola konten tren tersebut, sesuaikan dengan produkmu sendiri", "Buat 1 konten dengan hook yang jelas, pasang sebagai iklan dan ukur responsnya"]}, {"guid": "1e096f93-4951-42b9-94e7-de245ed3c351", "judul": "Konten Message untuk Iklan", "library": "321766", "poin_penting": ["Konten message = pesan inti tentang produk yang mau disampaikan", "Jangan cuma sebut fitur, ceritakan manfaatnya ('so what') bagi pembeli", "Satu produk bisa punya beberapa message untuk segmen berbeda", "Buat hipotesis message mana yang cocok untuk segmen mana, lalu testing"], "ringkasan": "Konten message adalah pesan yang ingin disampaikan ke pelanggan tentang produk — langkah pertama yang direncanakan sebelum testing iklan. Kesalahan umum penjual adalah hanya mempresentasikan fitur produk tanpa menceritakan 'so what'-nya (manfaatnya buat pembeli apa). Satu produk bisa punya banyak message berbeda untuk segmen pasar yang berbeda, misalnya tas dengan message kapasitas besar untuk anak kuliah.", "langkah_praktis": ["Tulis 1 fitur utama produkmu, lalu ubah jadi manfaat: 'pembeli dapat apa?'", "Buat 3 message berbeda untuk 3 segmen pembeli yang berbeda", "Tulis hipotesismu: message mana yang cocok untuk segmen mana", "Jalankan iklan kecil untuk tiap message dengan budget yang sama", "Bandingkan hasilnya setelah 3 hari — pertahankan yang menang, buang yang kalah"]}, {"guid": "21278b36-1b0a-45f7-a485-8d9e56b8eb59", "judul": "Alur Dropship via Marketplace (Transfer)", "library": "321766", "poin_penting": ["Alur: iklan → chat/order → pembeli transfer → order via marketplace → marketplace kirim ke pembeli", "Manfaatkan fitur 'kirim sebagai dropshipper' di marketplace", "Uang pembeli masuk dulu sebelum kita belanja — minim modal", "Jangan skip langkah, satu langkah kelewat bisa bikin bingung"], "ringkasan": "Penjelasan alur dropship memakai marketplace ketika pembeli membayar dengan transfer. Urutannya: pasang iklan, calon pembeli tertarik dan chat, pembeli membayar ke kita, kita order produk via marketplace memakai fitur dropship, marketplace kirim langsung ke alamat pembeli. Uang sudah masuk ke kita sebelum kita belanja ke marketplace, jadi tidak butuh modal stok.", "langkah_praktis": ["Pasang iklan produk dan arahkan calon pembeli chat ke WhatsApp", "Terima pembayaran transfer dari pembeli ke rekeningmu terlebih dahulu", "Buka marketplace, cari produk yang sama, aktifkan opsi 'kirim sebagai dropshipper'", "Isi alamat pembeli sebagai penerima dan selesaikan pembayaran ke marketplace", "Pantau status pengiriman sampai barang diterima pembeli, lalu kabari pembeli"]}, {"guid": "2c47db0e-ddce-4d34-a6a3-d310edbdf6cb", "judul": "Apa Itu Meta Ads?", "library": "321766", "poin_penting": ["Meta Ads mencakup Facebook, Instagram, WhatsApp dalam satu dashboard", "Facebook: cocok untuk target usia 35+ (paruh baya dan lansia)", "Tiap platform punya karakter konten dan demografi berbeda", "Pilih platform sesuai dengan target market produk"], "ringkasan": "Meta Ads adalah ekosistem periklanan di platform Meta: Facebook, Instagram, dan WhatsApp, semuanya dikelola lewat satu dashboard Ads Manager. Tiap platform punya karakter berbeda — Facebook fokus ke penyebaran informasi dan interaksi dengan pengguna dominan usia 35 tahun ke atas (117 juta pengguna aktif). Memahami karakter tiap platform membantu menentukan produk cocok diiklankan di mana.", "langkah_praktis": ["Buka business.facebook.com dan buat akun Business Manager", "Buat Fanpage untuk bisnismu, lengkapi foto dan deskripsinya", "Kenali target usiamu: usia 35+ fokus ke Facebook, anak muda fokus ke Instagram", "Pelajari dashboard Ads Manager: pahami susunan campaign, adset, dan ads", "Tentukan 1 platform utama untuk iklan pertamamu"]}, {"guid": "34de7c2f-747c-4be1-9963-07c28e7e0b5d", "judul": "Kenapa Harus Beriklan?", "library": "321766", "poin_penting": ["Brand besar pun tetap beriklan — untuk akselerasi jangkauan dan penjualan", "Iklan digital menjangkau lebih luas dan cepat dibanding offline", "Tentukan tujuan iklan dengan jelas: awareness atau penjualan", "Jangan mengharapkan penjualan langsung dari iklan yang tujuannya awareness"], "ringkasan": "Bahkan brand raksasa seperti Nike dan Apple tetap beriklan — tujuannya akselerasi, yaitu menjangkau calon pelanggan lebih luas dan lebih cepat dibanding cara offline seperti sebar brosur satu per satu. Sebelum beriklan, tujuan harus jelas: apakah untuk brand awareness (orang kenal brand) atau untuk penjualan langsung. Contoh brand air mineral yang kampanye 'ada manis-manisnya' fokus ke awareness dulu, bukan langsung mengejar penjualan.", "langkah_praktis": ["Tulis tujuan iklanmu dengan jelas: untuk awareness atau untuk penjualan", "Kalau tujuannya awareness: ukur dari jangkauan dan interaksi, bukan dari order", "Kalau tujuannya penjualan: siapkan alur order (chat/WA/landing page) yang siap menerima pembeli", "Hitung budget iklan yang siap kamu keluarkan per minggu", "Mulai dengan budget kecil dulu untuk belajar membaca data"]}, {"guid": "41429242-cd16-4a3c-9890-c559af6efa56", "judul": "Konten Type dan Konten Form", "library": "321766", "poin_penting": ["Konten type: monolog, sketsa, poster, voice over, testimoni, meme, dll", "Kombinasikan message × angle × type × form jadi banyak variasi", "Kalau satu kombinasi sudah jenuh, ganti type-nya dulu sebelum ganti message/angle", "Punya data testing membuat pembuatan konten tidak lagi tebak-tebakan"], "ringkasan": "Setelah message dan angle ditentukan, variasikan lewat konten type (bentuk penyajian) dan konten form agar tidak kehabisan ide. Pilihan type antara lain monolog, sketsa, poster, voice over, day in a life, testimoni, reality show, atau meme. Dengan mengombinasikan message × angle × type × form, satu produk bisa menghasilkan banyak variasi konten untuk terus di-testing.", "langkah_praktis": ["Ambil 1 message dan 1 angle produkmu yang sudah ada", "Buat 3 variasi type: monolog, testimoni, dan poster atau meme", "Jalankan ketiganya sebagai iklan terpisah dengan budget yang sama", "Setelah 3 hari bandingkan: type mana yang hasil per biayanya paling murah", "Kalau satu type sudah jenuh (hasil turun), ganti type-nya dulu sebelum ganti message atau angle"]}, {"guid": "4653b8f7-68d0-4a59-88fc-8632ce009524", "judul": "Dropship Marketplace: Next Level", "library": "321766", "poin_penting": ["Risiko dan peluang dropship marketplace lebih besar dari dropship biasa", "Syarat: sudah paham dropship tanpa modal dan testing produk CTWA", "Cocok untuk yang jauh dari supplier (luar Jawa)", "Untuk layanan COD harus berani menyetok dulu"], "ringkasan": "Dropship via marketplace disebut next level karena risikonya lebih besar tapi peluangnya juga lebih besar dibanding dropship biasa tanpa modal (seperti via Ostok). Materi ini untuk yang sudah paham dropship dasar dan sudah bisa testing produk via CTWA — bukan untuk pemula. Cocok terutama bagi yang tinggal jauh dari supplier (misal di luar Jawa) sehingga sulit mendapat produk dengan cepat, dengan catatan harus siap menyetok jika melayani COD.", "langkah_praktis": ["Pastikan kamu sudah paham dropship dasar dan pernah testing produk via CTWA", "Pilih marketplace yang pengirimannya cepat ke daerah target pembelimu", "Hitung risikonya: siapkan dana talangan untuk order ke marketplace", "Kalau melayani COD, siapkan stok di gudang atau rumah terlebih dahulu", "Mulai dari 1-2 produk yang sudah terbukti laku di testing CTWA"]}, {"guid": "488165cb-55d7-49bc-acd9-386107680f7d", "judul": "Trust dan Kredibilitas", "library": "321766", "poin_penting": ["Faktor kedua setelah harga: review/testimoni menentukan kepercayaan", "Minta testimoni asli pelanggan dan pajang di semua channel", "Dropshipper: isi kolom komentar iklan dengan testimoni positif", "Jadikan komplain sebagai bahan evaluasi perbaikan produk"], "ringkasan": "Setelah harga, faktor kedua yang dicek calon pembeli adalah rating, review, dan testimoni — ini yang membangun kepercayaan. Mintalah testimoni asli dari pelanggan yang sudah beli untuk dipajang di landing page, toko online, dan media sosial. Untuk dropshipper, optimalkan kolom komentar postingan iklan dengan testimoni yang bagus. Komplain pelanggan pun berguna sebagai masukan untuk memperbaiki kualitas produk.", "langkah_praktis": ["Chat 10 pembeli lamamu, minta testimoni jujur (boleh teks, foto, atau video)", "Pajang testimoni terbaik di landing page, bio, dan highlight media sosialmu", "Isi kolom komentar postingan iklan dengan 3-5 testimoni positif", "Kumpulkan setiap komplain, catat polanya, lalu perbaiki produk atau layananmu", "Perbarui pajangan testimoni secara berkala agar terlihat aktif"]}, {"guid": "5f73286b-3f9f-4ddc-a6b2-569952425948", "judul": "Kenapa Digital Marketing Itu Penting", "library": "321766", "poin_penting": ["Era digital memaksa adaptasi — yang tidak go-digital sulit bertahan (contoh Covid)", "Digital marketing = cara bertahan (eksistensi) sekaligus bertumbuh (ekspansi)", "Kebiasaan belanja orang sudah berubah ke online/marketplace", "Mengandalkan traffic pengunjung fisik saja membuat omzet menurun"], "ringkasan": "Dua alasan utama: eksistensi dan ekspansi. Era berubah cepat — saat Covid banyak toko offline gulung tikar (contoh Pasar Tanah Abang yang sepi), sedangkan yang melek digital bertahan bahkan berkembang. Digital marketing juga memungkinkan ekspansi jangkauan jauh melampaui keterbatasan lokasi fisik toko.", "langkah_praktis": ["Daftarkan 1 akun bisnis di marketplace atau aktifkan Instagram Shopping", "Pindahkan katalog produkmu ke format digital: foto jelas plus deskripsi", "Pelajari 1 channel digital yang paling dipakai target marketmu", "Alokasikan 1-2 jam per hari untuk belajar dan eksekusi digital", "Bandingkan omzet tiap bulan: sebelum dan sesudah go-digital"]}, {"guid": "5fc903be-e12d-43d5-b443-a8a5e8807df2", "judul": "Ads Content Praktis: Contoh Produk", "library": "321766", "poin_penting": ["Satu produk bisa punya banyak angle dari masalah yang berbeda", "Contoh angle: kebersihan garasi, bau, motor rusak, unsur ibadah", "Angle yang bagus = menyentuh pain spesifik segmen tertentu", "Cek angle yang dipakai kompetitor lewat Ad Library sebagai referensi"], "ringkasan": "Penerapan praktis message + angle + type + form lewat contoh produk pengusir kucing liar. Satu produk bisa dimainkan banyak angle berdasarkan masalah berbeda: garasi kotor, rumah bau, motor dicakar, sampai unsur ibadah (tidak kena najis saat sholat). Tiap angle menyasar rasa sakit (pain) yang berbeda pada segmen pembeli yang berbeda.", "langkah_praktis": ["Tulis 5 masalah berbeda yang bisa diselesaikan oleh produkmu", "Ubah tiap masalah jadi 1 angle iklan (contoh: bau, kotor, rusak, ibadah, hemat)", "Buat 1 konten singkat untuk masing-masing angle", "Buka Ad Library, cek angle apa yang dipakai kompetitor sebagai referensi", "Testing semua angle dengan budget kecil, naikkan budget untuk angle yang menang"]}, {"guid": "636ffc21-a23a-4731-962b-fad28216be57", "judul": "Handling Objection Pelanggan", "library": "321766", "poin_penting": ["80% penolakan pelanggan bersifat emosional, bukan logis", "Ragu ke toko → atasi dengan empati dan rasa aman", "Ragu ke produk → atasi dengan fakta (sertifikasi, uji lab)", "'Kok mahal?' → sepakati, lalu tunjukkan kualitas yang didapat"], "ringkasan": "Sekitar 80% keraguan pelanggan bersifat emosional (pikiran bawah sadar), bukan logis. Tiga penolakan paling umum: 'masih ragu', 'kok mahal?', dan 'pikir-pikir dulu'. Ragu terhadap toko diatasi dengan pendekatan emosional (bangun rasa aman), sedangkan ragu terhadap produk diatasi dengan fakta (misal sertifikasi BPOM). Untuk 'mahal', sepakati dulu lalu tunjukkan kualitas yang sepadan dengan harga.", "langkah_praktis": ["Catat 5 penolakan yang paling sering muncul di chat pembelimu", "Kelompokkan: ragu ke toko (emosional) vs ragu ke produk (butuh fakta)", "Siapkan jawaban empati untuk keraguan emosional, misal 'saya paham khawatirnya...'", "Siapkan bukti fakta untuk keraguan produk: sertifikasi, uji lab, atau garansi", "Untuk 'kok mahal?': sepakati dulu, lalu tunjukkan kualitas yang sepadan dengan harga"]}, {"guid": "6eb9e090-9823-434f-b4f2-4b19b98997b8", "judul": "Bangun Trust dengan Teknik Pacing", "library": "321766", "poin_penting": ["Pacing = samakan bahasa/kata kunci dengan yang dipakai pembeli", "Mengulang frasa pembeli membuat terasa dekat dan dipercaya", "Jangan menyangkal pendapat pelanggan — dengarkan dengan empati dulu", "Sampaikan fakta/penjelasan setelah pelanggan merasa didengar"], "ringkasan": "Teknik pacing dari hypno-selling dipakai untuk membangun kepercayaan dengan cepat lewat chat: samakan bahasa dan kata kunci yang dipakai calon pembeli. Contohnya jika pembeli bilang 'pengen bebas dari obat kimia', jawaban kita mengulang frasa yang sama agar terasa nyambung. Prinsip kedua adalah win-win solution: dengarkan pendapat pelanggan dengan empati dulu, jangan disangkal, baru sampaikan fakta setelahnya.", "langkah_praktis": ["Baca chat pembeli, catat kata atau frasa kunci yang dia pakai", "Balas dengan mengulang frasa yang sama agar terasa nyambung dan dekat", "Jangan menyangkal pendapatnya — dengarkan dan validasi dulu perasaannya", "Setelah dia merasa didengar, baru sampaikan fakta atau penjelasanmu", "Praktikkan di 5 chat berikutnya dan perhatikan perbedaan responsnya"]}, {"guid": "7d69afb8-2b10-4a76-9f04-ec3e88f932eb", "judul": "Testing Angle di Dashboard Meta", "library": "321766", "poin_penting": ["Testing angle hanya setelah produk terbukti winning", "Belum punya audiens → pakai advantage audience, biarkan AI Meta bekerja", "Atur wilayah spesifik jika ada alasan (misal toko fisik di kota tertentu)", "Produk fisik dengan opsi COD rawan retur (RTS) — pertimbangkan risikonya"], "ringkasan": "Panduan praktik testing angle konten iklan di dashboard Meta Ads untuk brand owner, product owner, dan dropshipper yang produknya sudah winning. Jangan testing angle sebelum produknya terbukti laku — fokus dulu menemukan produk yang cocok dengan akun iklan. Untuk yang belum punya audiens, biarkan Meta mencari sendiri (advantage audience) karena AI-nya sudah pintar; atur wilayah secara spesifik hanya jika memang ada alasan bisnisnya.", "langkah_praktis": ["Pastikan produkmu sudah winning (terbukti laku) sebelum testing angle", "Buka Ads Manager, duplikat adset yang sedang winning", "Ganti kontennya dengan angle baru, biarkan setting lain tetap sama", "Kalau belum punya audiens: pakai advantage audience, biarkan AI Meta yang bekerja", "Evaluasi setelah budget cukup terkumpul: angle mana yang ROAS-nya terbaik"]}, {"guid": "86b184ce-1a13-4e9c-b36a-e315b53ecb4e", "judul": "Intisari Digital Marketing", "library": "321766", "poin_penting": ["Digital marketing = marketing biasa yang dijalankan secara digital", "Kuasai esensi (target market, psikologi) sebelum main tools", "Bukan perubahan pilihan, melainkan keharusan di era informasi", "Bukan judi — semua terukur lewat data, bukan jalan pintas kaya"], "ringkasan": "Kesimpulan modul fundamental: digital marketing adalah kegiatan marketing yang dilakukan secara digital — prinsipnya sama dengan marketing offline, yang beda hanya tools dan cara penyampaiannya. Pahami dulu esensinya (target market, psikologi, demografi) sebelum terjun ke tools digital. Digital marketing bukan judi dan bukan jalan pintas kaya mendadak, melainkan sarana yang terukur lewat data.", "langkah_praktis": ["Tulis siapa target marketmu: usia, gender, dan kebiasaan online mereka", "Pelajari 1 psikologi dasar pembeli di niche-mu: kenapa mereka mau beli", "Kuasai 1 tools sampai benar-benar paham dulu, baru tambah tools lain", "Catat semua data iklanmu — jangan ambil keputusan dari feeling", "Ingat prinsipnya: ini bukan judi, yang menang adalah yang paling paham data"]}, {"guid": "86cd75fe-6f1b-470d-85aa-e28929769b1e", "judul": "Red Ocean vs Blue Ocean", "library": "321766", "poin_penting": ["Red ocean = pasar ramai kompetitor; blue ocean = pasar masih sepi", "Kelebihan red ocean: pasar sudah terbentuk, akuisisi cepat", "Peluang dominasi ada jika harga lebih murah dengan kualitas setara", "Kekurangan: persaingan intens dan posisi dominan tetap rentan"], "ringkasan": "Red ocean adalah pasar yang sudah ramai kompetitor dan terbentuk (zona perang harga), sedangkan blue ocean adalah pasar yang masih sepi. Kelebihan red ocean: pasarnya sudah ada sehingga tidak perlu edukasi, akuisisi pelanggan cepat, dan ada peluang mendominasi jika bisa lebih murah dengan kualitas setara. Kekurangannya: persaingan sangat ketat dan posisi yang sudah dominan pun tetap rentan diserang kompetitor.", "langkah_praktis": ["Petakan kompetitormu: siapa saja yang menjual produk sejenis", "Kalau pasarnya ramai (red ocean): cari celah harga lebih murah dengan kualitas setara", "Kalau pasarnya sepi (blue ocean): siapkan edukasi pasar karena belum terbentuk", "Hitung di pasar mana margin dan peluang menangmu lebih besar", "Pilih satu dan fokus — jangan setengah-setengah di dua pasar"]}, {"guid": "94344b67-d35a-4a0c-98ed-6fb7bcbbb9bc", "judul": "Apa Itu Google Ads?", "library": "321766", "poin_penting": ["Google Ads berbasis kata kunci dan bidding — butuh website", "Mindset terbalik dari medsos: pelanggan mencari kita, bukan kita mencari mereka", "Cocok untuk pasar yang sudah jelas dan terbentuk", "Tidak cocok untuk testing pasar yang belum ada"], "ringkasan": "Google Ads adalah ekosistem periklanan di mesin pencari Google dengan cara kerja yang berlawanan dengan media sosial: di Google, pelanggan yang datang mencari kita (berbasis kata kunci), sedangkan di medsos kita yang mendatangi pelanggan. Sistemnya memakai kata kunci dan bidding, serta membutuhkan website sebagai tujuan. Cocok untuk pasar yang sudah jelas, tidak cocok untuk testing pasar baru.", "langkah_praktis": ["Pastikan kamu punya website atau landing page sebagai tujuan iklan", "Riset kata kunci yang dipakai calon pembeli saat mencari produkmu di Google", "Buat akun Google Ads, mulai dengan 5-10 kata kunci paling relevan", "Ingat mindsetnya: di Google pembeli yang mencari kamu — siapkan jawaban terbaik", "Jangan pakai Google Ads untuk testing pasar baru, pakai media sosial dulu"]}, {"guid": "98f4ca4b-4eee-4034-ba92-7f85cf2d8c7c", "judul": "Content Angle: Pain, Gain, WTF", "library": "321766", "poin_penting": ["Tiga jenis angle: pain (kesusahan), gain (keinginan), WTF (tak terduga)", "Angle menentukan hook dan storytelling konten iklan", "Harus audience-centric — pahami kondisi audiens dulu", "Jangan cuma presentasi fitur, bangun cerita di baliknya"], "ringkasan": "Setelah punya content message, langkah berikutnya adalah menentukan content angle — sudut penyampaian yang mengarah ke hook dan storytelling. Ada tiga jenis angle: pain (menyentuh kesusahan/kekhawatiran), gain (menjanjikan keinginan/hasil), dan WTF (sesuatu yang tak terduga dan kreatif). Kuncinya tetap audience-centric: pahami dulu kondisi audiens sebelum memilih angle.", "langkah_praktis": ["Untuk produkmu, tulis 1 angle pain: kesusahan apa yang diatasi produk ini", "Tulis 1 angle gain: keinginan atau hasil apa yang didapat pembeli", "Tulis 1 angle WTF: sesuatu yang tak terduga dan bikin penasaran", "Pastikan semua angle audience-centric: sesuai dengan kondisi audiensmu", "Buat konten untuk ketiganya, testing mana yang paling menarik perhatian"]}, {"guid": "9df7cb14-67b2-4857-88c9-f26f0752fda2", "judul": "Apa Itu TikTok Ads?", "library": "321766", "poin_penting": ["TikTok = platform video, fokus hiburan, dominan pengguna muda", "128 juta pengguna aktif — sumber traffic sangat besar", "TikTok Shop terintegrasi Tokopedia, efektif untuk jualan", "Cocok untuk produk yang targetnya remaja/anak kuliah"], "ringkasan": "TikTok Ads adalah periklanan di ekosistem TikTok — sebuah platform berbagi video yang fokus ke hiburan dan informasi, sangat populer di kalangan muda. Pengguna aktifnya mencapai 128 juta (awal 2024), lebih banyak dari Facebook dan Instagram, dengan dominasi usia muda/remaja. Kelebihan khususnya adalah TikTok Shop yang terintegrasi dengan Tokopedia, sangat efektif untuk produk yang menyasar anak muda.", "langkah_praktis": ["Cek dulu: apakah target marketmu anak muda atau remaja? Kalau ya, TikTok cocok", "Buat akun TikTok Bisnis dan hubungkan ke TikTok Shop atau Tokopedia", "Pelajari format video pendek yang lagi tren di niche produkmu", "Buat 3 video organik dulu untuk pemanasan sebelum mulai beriklan", "Mulai iklan dengan konten yang terasa natural, bukan seperti iklan"]}, {"guid": "9e9f4bb5-12d2-40ff-aa8b-3b932c4756bb", "judul": "Teknik Closing via Chat", "library": "321766", "poin_penting": ["Pikiran bawah sadar suka memprediksi pola — manfaatkan untuk closing", "Pancing jawaban 'ya' berulang sebelum masuk ke penawaran", "Backtracking: rangkum fakta yang sudah disepakati pelanggan di chat", "Syaratnya harus gali dulu lewat chatting — kenali kebutuhan pelanggan"], "ringkasan": "Teknik closing memakai cara kerja pikiran bawah sadar yang suka memprediksi pola. Triknya seperti telemarketing: pancing jawaban 'ya' berkali-kali lewat pertanyaan ringan, lalu tutup dengan penawaran. Teknik backtracking merangkum fakta-fakta yang sudah disetujui pelanggan dalam chat (sudah pilih produk, produknya cocok, sudah dapat ongkir, sudah kirim alamat) sehingga secara psikologis mereka sulit berkata tidak.", "langkah_praktis": ["Sebelum closing, gali dulu lewat chat: apa kebutuhan dan masalah pembeli", "Ajukan 3-4 pertanyaan ringan yang jawabannya 'ya'", "Setelah dapat rentetan jawaban 'ya', baru sampaikan penawaranmu", "Pakai backtracking: rangkum yang sudah disepakati ('jadi sudah pilih X, alamat sudah...')", "Tutup dengan ajakan bertindak yang jelas, misal 'silakan transfer ke sini ya kak'"]}, {"guid": "a8c18f84-112d-4951-b9df-451ce2d26bd9", "judul": "Kenapa Orang Membeli", "library": "321766", "poin_penting": ["Tiga motif beli: hemat (cost/time), pain/gain, status/komunitas", "Kenali motif utama produkmu sebelum bikin materi jualan", "Contoh: obat = hilangkan pain, jam mewah = status", "Pesan iklan harus selaras dengan motif beli target pembeli"], "ringkasan": "Ada tiga motif dasar orang membeli: menghemat (uang atau waktu), pain/gain (mengurangi rasa sakit atau mendapatkan hasil), dan status/komunitas (pengakuan atau ikut-ikutan lingkungan). Contohnya pesawat dipilih karena hemat waktu, obat karena menghilangkan sakit, protein karena mengejar otot, dan jam mewah karena status. Penjual wajib tahu produknya menyasar motif yang mana agar pesannya tepat.", "langkah_praktis": ["Tentukan motif utama produkmu: menghemat, pain/gain, atau status", "Tulis ulang deskripsi produkmu agar menonjolkan motif tersebut", "Cek foto dan headline iklanmu: apakah sudah selaras dengan motifnya?", "Kalau produk menyasar 2 motif, buat materi iklan terpisah untuk tiap motif", "Tanya 3 pembelimu kenapa mereka beli — cocokkan dengan tebakan motifmu"]}, {"guid": "aa05c2da-5ad4-43c4-8f13-aebc9da6f18c", "judul": "Pengenalan Chat Mastery (NLP)", "library": "321766", "poin_penting": ["Chat Mastery = teknik membalas chat agar berujung closing (pendekatan NLP)", "Berlaku untuk WhatsApp, marketplace, dan Instagram", "Bisa dipakai sendiri atau diajarkan ke tim CS", "Jualan adalah seni memahami konsumen, bukan sekadar menawarkan"], "ringkasan": "Video pembuka modul Chat Mastery yang memakai pendekatan NLP untuk membalas pesan pelanggan di WhatsApp, marketplace, maupun Instagram agar berujung closing. Materi ini bisa dipraktikkan sendiri oleh dropshipper pemula atau diajarkan ke tim CS. Intinya: jualan adalah seni memahami calon konsumen dan menyampaikan maksud produk dengan cara yang tepat — modul ini mengupas tahapan chat dari sapaan pertama sampai closing.", "langkah_praktis": ["Siapkan template sapaan pembuka yang ramah untuk WA, marketplace, dan IG", "Petakan tahapan chat: sapa, gali kebutuhan, tawarkan, closing", "Latih 1 teknik per minggu, mulai dari kesan pertama", "Kalau punya tim CS, ajarkan 1 teknik dan minta langsung dipraktikkan", "Evaluasi tiap minggu: berapa chat yang berujung closing"]}, {"guid": "bc25fe43-c1fb-4e18-a17c-003555039f46", "judul": "Killing Offer", "library": "321766", "poin_penting": ["Killing offer = penawaran yang bikin pembeli rugi kalau tidak beli sekarang", "Teknik andalan: bundling (beli 1 dapat banyak)", "Cocok untuk produk konsumsi berulang (skincare, herbal)", "Susun tier harga agar paket terbesar terlihat paling menguntungkan"], "ringkasan": "Killing offer adalah penawaran yang membuat calon pembeli merasa rugi kalau tidak ambil sekarang juga — kunci pamungkas dalam formula winning, khusus untuk iklan hard selling. Teknik paling efektif adalah bundling (beli satu dapat banyak) yang cocok untuk produk habis pakai seperti skincare atau herbal. Contohnya paket saffron: makin besar paketnya, makin terasa hematnya sehingga pembeli terdorong ambil paket terbesar.", "langkah_praktis": ["Cek dulu: apakah produkmu habis pakai atau dibeli ulang? Kalau ya, cocok untuk bundling", "Susun 3 tier paket: kecil, sedang, besar — buat paket terbesar terlihat paling hemat", "Hitung margin tiap tier, pastikan semuanya tetap untung", "Tulis penawarannya dengan urgensi: bikin pembeli merasa rugi kalau tidak ambil sekarang", "Pasang di iklan hard selling dan ukur kenaikan konversinya"]}, {"guid": "d1ba5c9a-1341-4bf6-a92e-8762ef2aeecb", "judul": "Iklan Offline vs Online", "library": "321766", "poin_penting": ["Kelebihan offline: komunikasi real-time, cepat bangun trust", "Kekurangan offline: jangkauan terbatas, biaya mahal", "Iklan offline sulit/tidak bisa di-tracking hasilnya", "Online unggul karena jangkauan luas dan semua terukur data"], "ringkasan": "Jangan meremehkan offline: kelebihannya komunikasi real-time sehingga lebih cepat membangun trust dan cocok untuk target audiens yang spesifik. Namun iklan offline punya keterbatasan serius: jangkauan terbatas pada lokasi pemasangan, biaya mahal (banner bisa jutaan hingga ratusan juta), dan tidak bisa di-tracking hasilnya. Inilah alasan utama beralih ke online yang terukur.", "langkah_praktis": ["Kalau targetmu lokal dan spesifik: coba 1 media offline kecil seperti brosur atau flyer", "Catat biayanya dan estimasi jangkauannya untuk bahan perbandingan", "Bandingkan dengan budget yang sama di iklan online: mana yang lebih terukur hasilnya", "Manfaatkan momen tatap muka atau event offline untuk membangun trust cepat", "Tentukan alokasi budget offline vs online berdasarkan data, bukan asumsi"]}, {"guid": "d70fc952-ce53-445b-aac3-45867b0fe6a9", "judul": "Teknik Framing", "library": "321766", "poin_penting": ["Framing = targetkan iklan ke selain target market utama", "Hindari bidding mahal akibat berebut audiens yang sama dengan kompetitor", "Contoh: produk haid ditarget ke ayah/suami dengan pesan kasih sayang", "Butuh kreativitas mengemas pesan agar menyentuh hati target framing"], "ringkasan": "Teknik framing adalah cara menargetkan iklan bukan ke target market utamanya, agar terhindar dari persaingan bidding yang ramai. Contohnya produk nyeri haid: alih-alih menarget langsung ke wanita (yang juga ditarget semua kompetitor), iklan dibingkai untuk ayah/suami/pacar dengan pesan kasih sayang — 'belikan untuk putrimu/istrimu yang sering sakit saat haid'. Hasilnya biaya iklan lebih murah karena tidak berebut audiens yang sama.", "langkah_praktis": ["Identifikasi target market utama produkmu — yang juga ditarget semua kompetitor", "Pikirkan siapa di sekitar mereka yang peduli dan mau membelikan: ayah, suami, atau anak", "Kemas ulang pesan iklan untuk target framing itu, misal 'belikan untuk ibumu yang sering sakit'", "Buat 1 set iklan framing, jalankan paralel dengan iklan ke target utama", "Bandingkan biaya per hasilnya — iklan framing biasanya lebih murah"]}, {"guid": "d7eea1ce-9705-424f-b816-560a5cf2377e", "judul": "Apa Itu Digital Marketing?", "library": "321766", "poin_penting": ["Digital marketing = memasarkan sesuatu di platform/dunia digital", "95% ditentukan fundamental, 5% strategi — kuasai dasarnya dulu", "Manfaat: jangkauan audiens global dan brand awareness", "Berbeda dengan marketing offline konvensional (door-to-door, baliho)"], "ringkasan": "Video fundamental yang menjelaskan digital marketing: gabungan era digital (informasi lewat internet) dan marketing (cara memasarkan sesuatu). Disebutkan bahwa 95% keberhasilan bisnis ditentukan penguasaan fundamental, hanya 5% soal strategi. Manfaat utamanya: menjangkau audiens lebih luas (bahkan lintas negara) dan membangun brand awareness — contohnya Gojek dan Tokopedia yang masif beriklan di media sosial.", "langkah_praktis": ["Tulis definisi produk atau bisnismu dalam 1 kalimat yang jelas", "Daftar 3 platform digital tempat target marketmu berkumpul", "Pilih 1 platform untuk mulai, kuasai fundamentalnya terlebih dahulu", "Buat akun bisnis di platform itu dan lengkapi profilnya minggu ini", "Pasang target: dapatkan 1 interaksi atau order pertama dari channel digital dalam 30 hari"]}, {"guid": "ede00eab-5ea0-4944-9566-1edf76d47160", "judul": "Tools dan Platform Digital Marketing", "library": "321766", "poin_penting": ["Google Ads + Google Analytics untuk aktivitas periklanan di Google", "Email marketing dan platform manajemen order untuk operasional", "Google adalah mesin pencari utama di Indonesia", "Manfaatkan Google Business/Maps untuk pelanggan lokal"], "ringkasan": "Pengenalan tools dan platform yang umum dipakai di industri Indonesia: Google Ads dan Google Analytics untuk aktivitas di Google, email marketing (misal Mailchimp), serta platform manajemen order (seperti OrderOnline dan EverPro). Google dibahas khusus karena sudah menjadi top of mind mesin pencari di Indonesia. Google Business/Maps juga bisa dimanfaatkan untuk menjangkau pelanggan sekitar lokasi.", "langkah_praktis": ["Buat akun Google Business, lengkapi alamat dan jam buka tokomu", "Pasang Google Analytics di website atau landing page-mu", "Pilih 1 platform manajemen order dan daftarkan produkmu di sana", "Siapkan 1 tools email marketing untuk mengumpulkan database pelanggan", "Cek tiap minggu: dari tools mana traffic dan order terbanyak datang"]}, {"guid": "f144e19d-e44d-4141-9a18-f1a8ac3afa8c", "judul": "Audience Centric untuk Ads Content", "library": "321766", "poin_penting": ["Kuasai audience centric dulu sebelum bikin ads content", "Empat aspek ads content: message, angle, type, form", "Semuanya harus dianalisis dan direncanakan sebelum testing", "Tidak bisa asal bikin — harus sistematis"], "ringkasan": "Video pengantar yang menegaskan pentingnya menguasai audience centric sebelum membuat ads content. Berbeda dengan konten organik, ads content punya empat aspek yang harus dianalisis dan di-testing: content message, content angle, content type, dan content form. Keempatnya harus direncanakan matang sebelum beriklan, tidak bisa asal buat.", "langkah_praktis": ["Tulis profil audiensmu: apa masalah, keinginan, dan bahasa sehari-hari mereka", "Sebelum bikin konten, tentukan dulu: message apa, angle apa, type apa, form apa", "Buat checklist 4 aspek itu untuk setiap konten iklan yang akan dibuat", "Jangan produksi konten sebelum keempatnya jelas", "Review tiap minggu: konten mana yang paling audience-centric dan paling menang"]}, {"guid": "f7b9024a-c699-4faa-9d58-ffaf6e92900b", "judul": "Boncos Adalah Cuan Tertunda", "library": "321766", "poin_penting": ["Boncos = biaya iklan keluar tapi hasil belum sesuai harapan", "Maknai sebagai 'cuan yang tertunda' — akan ketutup seiring bisa baca data", "Setiap boncos online menghasilkan data untuk diagnosis", "Data adalah fakta — jangan mengambil keputusan berdasar asumsi"], "ringkasan": "Boncos adalah kondisi ketika biaya iklan sudah keluar tapi hasilnya belum sesuai harapan — dimaknai sebagai 'cuan yang tertunda', bukan kegagalan. Kelebihan beriklan online: setiap boncos menghasilkan data sehingga bisa didiagnosis penyebabnya (konten kurang menarik? landing page lambat? harga kemahalan?). Berbeda dengan offline seperti baliho yang boncos tanpa tahu salahnya di mana. Kuncinya: data adalah fakta, jangan abaikan.", "langkah_praktis": ["Setiap iklan boncos: jangan panik, buka datanya dan catat angkanya", "Diagnosis satu per satu: CTR rendah berarti konten kurang menarik; klik banyak tapi tidak beli berarti masalah di landing page atau harga", "Buat jurnal boncos: tanggal, budget, dugaan penyebab, dan perbaikan yang dicoba", "Tetapkan batas boncos harian yang masih bisa kamu toleransi", "Ingat: data dari boncos adalah modal untuk iklan berikutnya yang profit"]}, {"guid": "fef43c05-9900-4540-a773-a25d28768303", "judul": "Mindset Jualan di Dunia Digital", "library": "321766", "poin_penting": ["Modal mulai bisnis online jauh lebih kecil dari offline", "Jangkauan online tidak terbatas lokasi fisik", "Biaya operasional online lebih ringan (tanpa sewa & gaji karyawan)", "Adaptasi ke digital adalah keharusan, bukan pilihan"], "ringkasan": "Perbandingan mindset jualan online vs offline. Bisnis online bisa dimulai dengan modal sangat kecil (bahkan di bawah 1 juta via CTWA), sedangkan bisnis offline butuh sewa tempat, karyawan, dan biaya bulanan yang besar. Jangkauan online pun tidak terbatas lokasi. Pesannya: era sudah berubah, yang tidak beradaptasi ke digital akan tertinggal.", "langkah_praktis": ["Hitung modal awalmu: targetkan mulai di bawah 1 juta lewat CTWA", "Pilih 1 produk saja untuk mulai — jangan langsung banyak", "Siapkan WA bisnis plus katalog sederhana minggu ini", "Buat 1 iklan pertama dengan budget harian kecil, misal 50-100 ribu", "Komitmen evaluasi tiap 3 hari, jangan berhenti hanya di iklan pertama"]}, {"guid": "02c3bbba-fd4e-4313-8fc2-60e54662b2a7", "judul": "Setting Funnel LPWA (Landing Page ke WhatsApp)", "library": "321773", "poin_penting": ["LPWA = landing page dengan satu tombol utama yang mengarah ke WhatsApp", "Gunakan link WhatsApp generator untuk tombol, lalu tempel di pengaturan tombol", "Pasang pixel event AddToCart pada tombol agar klik bisa dilacak", "Selalu tes funnel lewat Event Manager sebelum iklan dijalankan"], "ringkasan": "Video ini menjelaskan cara membuat funnel LPWA, yaitu landing page yang tombolnya langsung mengarah ke WhatsApp. Tombol seperti Beli Sekarang atau Konsultasi disambungkan ke link WhatsApp, dan dipasangi pixel event AddToCart supaya bisa dilacak. Di akhir ada cara mengetes funnelnya lewat Event Manager.", "langkah_praktis": ["Buat link WhatsApp lewat generator (isi nomor + teks sapaan otomatis).", "Buka halaman landing page kamu, klik tombol utama, tempel link WhatsApp tadi di pengaturan tombol.", "Buka Event Manager Meta, salin kode pixel event AddToCart.", "Pasang kode AddToCart pada tombol WhatsApp di landing page.", "Klik tombolnya sendiri dari HP, lalu cek di Event Manager apakah event AddToCart tercatat."]}, {"guid": "05cba869-0eb8-44de-925b-2582e5ee4148", "judul": "Pengantar Modul Advanced Landing Page", "library": "321773", "poin_penting": ["Landing page yang bagus adalah salah satu kunci naiknya penjualan", "Jangan hanya mengandalkan template bawaan platform", "Modul ini fokus pada pembuatan landing page high conversion dengan AI"], "ringkasan": "Video pembuka modul Advanced Landing Page yang menjelaskan kenapa landing page penting untuk menaikkan penjualan. Materi ini mengajarkan cara membuat landing page berkualitas tinggi dengan bantuan AI, bukan sekadar memakai template bawaan platform. Peserta diminta menonton sampai habis agar paham konsepnya.", "langkah_praktis": ["Tonton seluruh video di modul ini berurutan, jangan loncat-loncat.", "Catat 3 hal yang paling relevan dengan produkmu saat ini.", "Bandingkan landing page-mu sekarang dengan standar yang diajarkan di modul ini.", "Tandai bagian mana yang akan kamu perbaiki duluan setelah modul selesai."]}, {"guid": "0db23598-142d-4969-b739-f466a087c739", "judul": "Membuat Landing Page Produk Digital dengan AI", "library": "321773", "poin_penting": ["Siapkan brief dulu: masalah target, keberatan beli, harga, dan deskripsi produk", "Generate prompt dari tools, lalu hasilkan kode landing page", "Gunakan Google Anti-Gravity untuk mempercantik desain, tambah gambar, dan optimasi kecepatan", "Semua revisi cukup lewat perintah teks, tidak perlu coding manual"], "ringkasan": "Praktik membuat landing page untuk produk digital (ebook) memakai tools AI: isi brief produk, generate prompt, lalu hasilkan kode landing page. Hasilnya kemudian dipercantik memakai Google Anti-Gravity, AI yang bisa mengedit kode, membuat gambar, dan mengoptimalkan kecepatan halaman otomatis.", "langkah_praktis": ["Tulis brief produk: masalah target, keberatan beli, harga, deskripsi singkat.", "Buka tools AI generator, isi brief, lalu generate prompt-nya.", "Tempel prompt ke AI, hasilkan kode landing page.", "Buka Google Anti-Gravity, minta percantik desain + tambahkan gambar produk.", "Minta AI optimasi kecepatan halaman, lalu preview hasilnya di HP."]}, {"guid": "1e30f60c-6115-428b-8b97-e25dea7c42b6", "judul": "Landing Page vs Website: Perbedaan dan Fungsinya", "library": "321773", "poin_penting": ["Landing page = satu produk, satu tombol aksi; website = banyak produk, banyak tujuan", "Gunakan landing page untuk produk penetrasi agar mudah mengakuisisi customer baru", "Landing page adalah satu level di atas CTWA: pembeli lebih serius karena sudah membaca dulu", "Pastikan isi iklan selaras dengan isi landing page agar pengunjung tidak bingung"], "ringkasan": "Video ini menjelaskan perbedaan mendasar antara landing page dan website. Landing page fokus pada satu produk dan satu aksi saja, sedangkan website mempresentasikan brand dengan banyak halaman dan tujuan. Landing page juga memudahkan pemasangan pixel dan cocok untuk mengakuisisi pembeli baru.", "langkah_praktis": ["Tentukan dulu: kamu jual SATU produk (pakai landing page) atau banyak produk/brand (pakai website).", "Kalau produk penetrasi untuk cari customer baru, buat landing page satu produk satu tombol.", "Pastikan headline iklan dan headline landing page isinya selaras.", "Pasang pixel di landing page agar traffic bisa di-retargeting."]}, {"guid": "24773971-01e9-4bd6-9fe5-1d23a85d6c04", "judul": "Studi Kasus: Custom Landing Page di Scalev", "library": "321773", "poin_penting": ["Ganti link teks biasa menjadi button agar terlihat profesional dan bisa diklik", "Gunakan ChatGPT untuk membuat kode button, lalu tempel di OneCompiler", "Buat halaman checkout terpisah untuk produk digital (tanpa kolom alamat)", "Pastikan setiap tombol mengarah ke tujuan yang benar sebelum dipublish"], "ringkasan": "Studi kasus mengubah landing page hasil AI agar siap dipasang di Scalev. Tombol-tombol yang masih berupa link teks diganti menjadi button yang mengarah ke bagian harga atau halaman checkout, dengan bantuan ChatGPT dan OneCompiler. Juga dibuat halaman checkout khusus untuk produk digital.", "langkah_praktis": ["Buka landing page hasil AI, tandai semua link teks yang perlu jadi button.", "Minta ChatGPT buatkan kode button yang mengarah ke bagian harga/checkout.", "Tempel kode di OneCompiler untuk cek tampilannya.", "Buat halaman checkout terpisah khusus produk digital (tanpa kolom alamat).", "Klik semua tombol satu per satu, pastikan tujuannya benar sebelum publish."]}, {"guid": "24f6b3f0-89d4-410e-ae7c-1230fa222bd6", "judul": "Framework Landing Page Simple (6 Section)", "library": "321773", "poin_penting": ["Struktur: headline tanya - solusi - masalah - benefit - testimoni - promo", "Headline berupa pertanyaan yang langsung menyentuh masalah calon pembeli", "Cocok untuk produk fungsional yang tidak perlu edukasi panjang", "Sertakan foto asli produk (real picture) untuk membangun kepercayaan"], "ringkasan": "Framework landing page versi ringkas dengan 6 bagian: headline pertanyaan, solusi, masalah target, benefit, testimoni, dan promo. Cocok untuk produk yang tidak butuh penjelasan panjang seperti casing HP atau alat rumah tangga, di mana pembeli lebih mementingkan fungsi.", "langkah_praktis": ["Tulis headline berupa pertanyaan yang menyentuh masalah calon pembeli.", "Susun 6 section berurutan: headline tanya, solusi, masalah, benefit, testimoni, promo.", "Siapkan foto asli produk (real picture), bukan foto katalog.", "Cek: apakah orang awam paham produknya dalam 10 detik pertama?"]}, {"guid": "479b02d3-3b05-4eed-bac2-21819a437d6d", "judul": "Framework Landing Page Panjang (9 Section)", "library": "321773", "poin_penting": ["9 section: goal, masalah, solusi, keuntungan, testimoni, fitur, promo, FAQ, kerugian", "Habiskan waktu terbanyak di headline karena menentukan pengunjung bertahan atau pergi", "Testimoni boleh dibuat tapi jangan overclaim yang tidak bisa dibuktikan", "Gunakan FAQ untuk menjawab keberatan sekaligus menonjolkan keunggulan (flexing)"], "ringkasan": "Framework lengkap 9 bagian untuk produk yang butuh penjelasan detail: produk solusi, produk mahal, atau produk digital. Urutannya: goal terbesar, masalah, solusi, keuntungan, testimoni, fitur, promo, FAQ, dan kerugian jika tidak beli. Ditekankan agar tidak overclaim pada testimoni.", "langkah_praktis": ["Tulis headline dulu — luangkan waktu paling lama di bagian ini.", "Susun 9 section: goal terbesar, masalah, solusi, keuntungan, testimoni, fitur, promo, FAQ, kerugian jika tidak beli.", "Tulis FAQ yang sekaligus menjawab keberatan dan menonjolkan keunggulan.", "Cek testimoni: hapus klaim yang tidak bisa kamu buktikan (hindari overclaim).", "Baca ulang dari atas: pastikan alurnya mengalir seperti cerita."]}, {"guid": "55eef404-a2cd-4dcc-8523-faa26324ee30", "judul": "Membuat Landing Page dengan Berdu", "library": "321773", "poin_penting": ["Berdu cocok untuk brand karena opsi desainnya lebih kaya", "Fitur drag and drop memudahkan mengubah urutan section", "Coba dulu beberapa platform (Weebly, OrderOnline, Berdu) lalu pilih yang paling cocok", "Untuk dropship cukup pakai OrderOnline; untuk brand, kombinasikan Berdu + OrderOnline"], "ringkasan": "Tutorial memakai page builder Berdu untuk membuat landing page, terutama untuk brand owner. Berdu punya lebih banyak opsi desain dibanding platform lain, termasuk fitur drag and drop untuk mengubah urutan section dengan mudah. Prinsipnya sama seperti page builder lain: tinggal tarik dan letakkan elemen.", "langkah_praktis": ["Daftar akun Berdu, buat halaman baru.", "Pilih template yang paling dekat dengan gayamu, lalu ubah urutan section dengan drag and drop.", "Ganti teks, gambar, dan tombol sesuai produkmu.", "Bandingkan hasilnya dengan versi Weebly/OrderOnline, pilih yang paling enak dipakai.", "Catatan: untuk dropship cukup OrderOnline; Berdu lebih cocok untuk brand."]}, {"guid": "575c10a0-57b9-4100-8d7c-992b9029a8e8", "judul": "Memindahkan Landing Page AI ke Scalev", "library": "321773", "poin_penting": ["Tempel kode HTML hasil AI ke komponen HTML di blank page Scalev", "Buat halaman checkout terpisah, lalu arahkan semua tombol ke sana via perintah AI", "Upload gambar ke Scalev lalu ganti URL gambar di kode agar tampil", "Atur margin ke nol di tampilan mobile dan desktop agar rapi"], "ringkasan": "Lanjutan dari pembuatan landing page AI: cara memindahkan hasilnya ke Scalev. Kode HTML ditempel ke blank page Scalev, lalu dibuat halaman checkout terpisah. Semua tombol diarahkan ke halaman checkout lewat perintah ke AI, dan gambar diganti dengan yang diupload ke Scalev agar tampil sempurna.", "langkah_praktis": ["Buka Scalev, buat blank page baru, tambahkan komponen HTML.", "Tempel seluruh kode HTML hasil AI ke komponen tersebut.", "Buat halaman checkout terpisah di Scalev.", "Perintahkan AI: arahkan semua tombol ke halaman checkout tadi.", "Upload semua gambar ke Scalev, ganti URL gambar di kode dengan URL Scalev.", "Atur margin ke nol untuk tampilan mobile dan desktop, lalu preview."]}, {"guid": "7c700c77-cc93-48e7-b814-d3c0dae8a121", "judul": "Pengenalan Tools AI Landing Page Generator", "library": "321773", "poin_penting": ["Pilih framework (PAS/AIDA), gaya bahasa, dan jenis produk sesuai kebutuhan", "Tentukan level awareness target market agar pesan tepat sasaran", "Isi detail produk: nama, harga coret, harga promo, benefit, dan keberatan beli", "Atur visual: warna, tema, mockup, plus fitur seperti sticky button dan countdown"], "ringkasan": "Pengenalan lengkap fitur tools AI pembuat landing page: pilihan framework copywriting (PAS, AIDA), gaya bahasa, jenis produk, tujuan konversi, level kesadaran target market, detail produk dan harga, hingga identitas visual seperti warna, tema, dan jenis mockup. Semua bisa diatur lewat checklist.", "langkah_praktis": ["Buka tools AI generator, pilih framework copywriting (PAS atau AIDA).", "Pilih gaya bahasa dan jenis produk yang sesuai.", "Tentukan tujuan konversi (beli, chat WA, isi form) dan level awareness target market.", "Isi detail: nama produk, harga coret, harga promo, benefit, keberatan beli.", "Atur visual: warna, tema, mockup; aktifkan sticky button dan countdown bila perlu.", "Generate, lalu review hasilnya sebelum dipakai."]}, {"guid": "80b1f3de-44ed-4f0f-b8e4-c5d7c8ad0bde", "judul": "100 Prompt Customisasi Landing Page", "library": "321773", "poin_penting": ["100 prompt customisasi tersedia di bawah video, tinggal copy-paste", "Tempel prompt ke AI untuk merevisi landing page", "Kerjakan banyak revisi sekaligus dalam satu perintah agar efisien"], "ringkasan": "Video singkat yang membagikan 100 prompt siap pakai untuk mengcustomisasi landing page agar lebih convert. Prompt tinggal dicopy lalu ditempel ke AI. Tipsnya: lakukan banyak revisi sekaligus dalam satu perintah agar tidak menunggu lama berkali-kali.", "langkah_praktis": ["Buka daftar 100 prompt di bawah video, pilih yang sesuai kebutuhanmu.", "Copy prompt-nya, tempel ke AI bersama link/kode landing page-mu.", "Gabungkan beberapa revisi dalam SATU perintah agar hemat waktu.", "Cek hasil revisinya, ulangi bila masih kurang pas."]}, {"guid": "844d75b1-2139-43ad-b18d-e33b41e74817", "judul": "Setting Checkout Page di OrderOnline", "library": "321773", "poin_penting": ["Sederhanakan form: cukup nama, nomor WA, dan alamat lengkap", "Sembunyikan rincian harga/ongkir di form agar tidak membuat ragu", "Aktifkan notifikasi email agar tahu setiap ada order masuk", "Setting teks follow-up otomatis supaya bisa follow up via WhatsApp langsung dari email"], "ringkasan": "Tutorial lengkap membuat checkout page yang dimodifikasi agar terlihat seperti landing page simple. Form disederhanakan (nama, WA, alamat), harga dan ongkir disembunyikan dari form, ditambah testimoni dan gambar. Setelah order masuk, aktifkan notifikasi email dan teks follow-up otomatis via WhatsApp.", "langkah_praktis": ["Buka OrderOnline, buat/edit halaman checkout.", "Sederhanakan form: sisakan nama, nomor WA, dan alamat lengkap saja.", "Sembunyikan rincian harga dan ongkir dari tampilan form.", "Tambahkan testimoni dan gambar produk di halaman checkout.", "Aktifkan notifikasi email agar tahu setiap ada order masuk.", "Setting teks follow-up otomatis supaya bisa lanjut chat via WhatsApp."]}, {"guid": "880a6d87-c7b7-4be4-b99d-1258d1922544", "judul": "Mengoptimalkan Copywriting untuk Konversi", "library": "321773", "poin_penting": ["Kenali profil dan bahasa target market sebelum menulis", "Posisikan diri sebagai pembeli: apa yang bikin ragu untuk beli?", "Sesuaikan gaya bahasa dengan audience, hindari bahasa kasar", "Copywriting sehebat apapun gagal jika visual, value, dan harga tidak sepadan"], "ringkasan": "Video ini membahas cara merangkai kata agar lebih tepat sasaran dan mendorong pembelian. Kuncinya: kenali audience dan bahasanya, posisikan diri sebagai pembeli, dan sesuaikan gaya bahasa dengan target (misalnya lebih halus untuk orang tua). Copywriting yang bagus harus didukung visual, value produk, dan harga yang sepadan.", "langkah_praktis": ["Tulis profil target market: umur, bahasa sehari-hari, masalahnya.", "Posisikan diri sebagai pembeli, tulis 3 hal yang bikin ragu untuk beli.", "Tulis ulang copy dengan bahasa yang sesuai audience (misal lebih halus untuk orang tua).", "Cek ulang: apakah visual, value produk, dan harga sudah sepadan dengan janji di copy?", "Minta 2-3 orang baca: apakah mereka paham dan tertarik?"]}, {"guid": "8a7eb657-eafb-472c-8561-5fdb7698c288", "judul": "Membuat Produk Digital dengan Bantuan AI", "library": "321773", "poin_penting": ["Validasi ide dulu sebelum membuat produk: masalah, kompetitor, target pembeli", "Isi brief selengkap mungkin agar analisis AI akurat", "Gunakan hasil generate sebagai panduan membuat produk digital", "Mulai dari tahap ideasi, lanjutkan setelah ada pembeli pertama"], "ringkasan": "Tutorial membuat produk digital memakai tools AI, dimulai dari validasi ide bisnis. Pengguna mengisi brief (masalah yang diselesaikan, kompetitor, target customer, kekhawatiran), lalu AI membantu menganalisis dan men-generate prompt dalam format dokumen. Prosesnya bertahap dari ideasi sampai siap dibuat.", "langkah_praktis": ["Tulis ide produkmu dalam satu kalimat: masalah apa yang diselesaikan untuk siapa.", "Isi brief validasi: masalah, kompetitor, target customer, kekhawatiran pembeli.", "Minta AI menganalisis brief dan memberi masukan.", "Minta AI generate outline/dokumen panduan pembuatan produk.", "Ikuti panduan tahap demi tahap; jangan lanjut ke tahap berikut sebelum tahap ini jelas.", "Target: dapatkan pembeli pertama sebelum menyempurnakan produk."]}, {"guid": "8e79f570-efa0-4586-b02d-cfcbea4b541d", "judul": "Setting Landing Page Full Form 2 Halaman di Formula", "library": "321773", "poin_penting": ["Halaman 1 untuk info produk, halaman 2 untuk form checkout", "Pasang pixel AddPaymentInfo di form dan Purchase saat order berstatus processing", "Aktifkan server-side tracking dan isi Pixel ID, nama, serta access token", "Sederhanakan kolom form dan beri petunjuk jelas di placeholder nomor WA"], "ringkasan": "Panduan setting landing page 2 halaman di Formula.com: halaman utama berisi info produk dan halaman kedua berisi form checkout. Dijelaskan cara tambah produk fisik, atur tema, isi deskripsi dan gambar, setting form pemesanan, pasang pixel AddPaymentInfo, serta aktifkan pixel Purchase dengan server-side tracking saat order diproses.", "langkah_praktis": ["Buka Formula.com, buat 2 halaman: halaman 1 info produk, halaman 2 form checkout.", "Tambahkan produk fisik: isi nama, tema, deskripsi, dan gambar.", "Sederhanakan kolom form; beri contoh format di placeholder nomor WA.", "Pasang pixel AddPaymentInfo di halaman form.", "Aktifkan server-side tracking: isi Pixel ID, nama, dan access token.", "Buat satu order percobaan, pastikan pixel Purchase terpicu saat status processing."]}, {"guid": "8fc6c096-e73a-412c-8a22-a6dff0c1320e", "judul": "Memahami Tujuan dan Target Audience", "library": "321773", "poin_penting": ["Bedakan pembeli karena butuh vs karena ingin, cara iklannya berbeda", "Gali 3 hal: problem mereka, solusi yang diharapkan, ketakutan terbesar", "Lakukan riset/wawancara ke pembeli yang sudah pernah beli", "Semakin banyak insight, semakin banyak variasi headline yang bisa dites"], "ringkasan": "Fondasi copywriting: pahami dulu kenapa target market membeli produk kita. Orang membeli karena punya masalah yang ingin diselesaikan (butuh) atau karena keinginan (ingin). Gali problem, solusi yang diharapkan, dan ketakutan terbesar mereka lewat riset atau wawancara pembeli agar headline dan iklan tepat sasaran.", "langkah_praktis": ["Tulis satu kalimat: kenapa orang membeli produkmu — karena butuh atau karena ingin?", "Wawancarai 3-5 pembeli lama: apa masalahnya, solusi apa yang diharapkan, apa ketakutan terbesarnya.", "Catat kata-kata persis yang mereka pakai (untuk bahan headline).", "Kelompokkan insight ke dalam problem, solusi, dan fear.", "Simpan daftarnya — ini bahan untuk bikin banyak variasi headline dan iklan."]}, {"guid": "b1ce57d6-c922-4b4a-a285-5b33ad7877ef", "judul": "Membuat Landing Page dari Nol dengan AI", "library": "321773", "poin_penting": ["Generate prompt dulu sebelum generate landing page agar hasilnya maksimal", "Edit/hapus section yang tidak perlu di OneCompiler sebelum dipasang", "Tempel kode ke Scalev via komponen HTML di blank page", "Sesuaikan warna dan cek tampilan mobile sebelum publish"], "ringkasan": "Praktik penuh membuat landing page dari nol: generate prompt dari ide produk, hasilkan kode via AI, edit section yang tidak perlu di OneCompiler, lalu pasang di Scalev lewat komponen HTML. Juga dijelaskan cara menyesuaikan warna dan memastikan tampilan bagus di HP.", "langkah_praktis": ["Tulis ide produk dalam 2-3 kalimat, lalu minta AI generate prompt landing page.", "Tempel prompt ke AI, hasilkan kode landing page.", "Buka OneCompiler, hapus section yang tidak perlu dari kode.", "Buka Scalev, buat blank page, tempel kode via komponen HTML.", "Sesuaikan warna sesuai brand, cek tampilan di HP, lalu publish."]}, {"guid": "b5bf5af6-b225-44f8-9379-e0ae1551a8b5", "judul": "Cara Scoring Landing Page dengan AI", "library": "321773", "poin_penting": ["Screenshot full page landing page, lalu minta AI menganalisis dan memberi skor", "Ambil saran yang relevan saja, abaikan yang tidak sesuai target", "Eksekusi perbaikan lewat perintah ke AI, terima konfirmasi yang muncul", "Ulangi scoring setelah revisi untuk memastikan skor naik"], "ringkasan": "Cara menilai kualitas landing page memakai AI: screenshot seluruh halaman dengan extension browser, lalu minta ChatGPT menganalisis dan memberi skor. Dari hasil analisis, ambil saran perbaikan yang relevan (misalnya CTA kurang agresif atau belum ada scarcity), lalu eksekusi perbaikannya lewat AI.", "langkah_praktis": ["Install extension screenshot full page di browser.", "Screenshot seluruh landing page-mu dari atas sampai bawah.", "Upload screenshot ke ChatGPT, minta analisis + skor 1-100.", "Baca sarannya, pilih yang relevan saja (misal CTA kurang agresif).", "Perintahkan AI untuk eksekusi perbaikan yang kamu pilih.", "Ulangi scoring setelah revisi, pastikan skornya naik."]}, {"guid": "b5dc3980-f2a2-4fe5-85c2-53f8e1765cf9", "judul": "Framework Landing Page Super Simple (3 Section)", "library": "321773", "poin_penting": ["Struktur: produk - benefit - promo, singkat padat jelas", "Tampilkan foto/video produk sedang digunakan, bukan sekadar foto produk", "Cocok untuk dropship; kurang cocok untuk brand yang butuh loyalitas", "Besarkan elemen promo: harga coret, COD, gratis ongkir, dan tombol beli"], "ringkasan": "Framework paling ringkas: hanya 3 bagian yaitu produk, benefit, dan promo. Sangat cocok untuk dropshipper yang sering ganti produk, seperti alat rumah tangga atau otomotif. Tidak cocok untuk brand karena tidak membangun kedekatan jangka panjang dengan pembeli.", "langkah_praktis": ["Siapkan 3 bahan: foto/video produk, 3-5 benefit singkat, dan promo (harga coret, COD, gratis ongkir).", "Susun 3 section: produk (foto/video sedang dipakai) - benefit - promo.", "Besarkan elemen promo: harga coret harus langsung terlihat.", "Pastikan tombol beli ada di bagian promo dan mudah diklik dari HP.", "Catatan: framework ini untuk dropship ganti-ganti produk, bukan untuk brand."]}, {"guid": "b8a4c59d-1b93-4da5-acf0-43d223f3c20c", "judul": "CTWA vs Landing Page: Pilih Journey yang Tepat", "library": "321773", "poin_penting": ["CTWA: biaya per chat murah, closing rate bagus 10-30%, tapi lead mentah", "Landing page: menyaring pembeli serius, cocok saat ingin mengurangi chat tanya-tanya", "Kekurangan CTWA: sangat tergantung kecepatan dan skill CS membalas chat", "Pilih sesuai kondisi: CTWA untuk mulai cepat, landing page untuk scale up"], "ringkasan": "Perbandingan dua journey iklan: CTWA (klik iklan langsung ke WhatsApp) vs Landing Page. CTWA murah per chat dan bisa langsung interaksi, tapi lead-nya mentah dan sangat tergantung skill closing CS. Landing page memfilter pembeli lebih serius tapi journey-nya lebih rumit dengan beberapa variasi arah.", "langkah_praktis": ["Jawab jujur: CS-mu cepat balas chat dan jago closing? Kalau ya, CTWA bisa jadi pilihan.", "Kalau chat kebanyakan tanya-tanya tidak beli, saatnya coba landing page untuk filter.", "Untuk mulai cepat dengan budget kecil: pilih CTWA dulu.", "Untuk scale up dan mengurangi beban CS: pindah ke landing page.", "Jangan campur: satu campaign satu journey, ukur closing rate masing-masing (target CTWA 10-30%)."]}, {"guid": "cebbf972-84cc-4896-a2d3-88f0e88c9c6c", "judul": "Membuat Headline yang Menarik", "library": "321773", "poin_penting": ["Rumus: mainkan problem, solusi, dan fear dalam satu kalimat", "Contoh: atasi hipertensi tanpa khawatir gagal ginjal karena obat kimia", "Headline harus selaras dengan isi iklan dan target market", "Untuk produk solusi, luangkan waktu lebih di headline karena sangat menentukan"], "ringkasan": "Teknik membuat headline dengan rumus memainkan tiga elemen: problem, solusi, dan fear (ketakutan). Contoh rumusnya: bagaimana cara [solusi] tanpa [fear], atau [selesaikan problem] sebelum [fear datang]. Headline yang baik membuat orang berhenti scroll karena merasa relate dengan kondisinya.", "langkah_praktis": ["Tulis problem, solusi, dan fear produkmu masing-masing satu baris.", "Rangkai dengan rumus: 'Bagaimana cara [solusi] tanpa [fear]' atau '[selesaikan problem] sebelum [fear datang]'.", "Buat 5 variasi headline, pilih 2 terbaik.", "Cek: apakah orang yang scroll berhenti karena merasa relate?", "Pastikan headline selaras dengan isi iklan dan target market."]}, {"guid": "dd5e1b32-5691-4b49-8fc6-1e9f8b0c8d32", "judul": "Membuat Landing Page dengan OrderOnline", "library": "321773", "poin_penting": ["Buat section dulu sebelum memasukkan elemen (beda dengan Berdu)", "Atur tampilan mobile sejak awal karena mayoritas traffic dari HP", "Setiap tombol/gambar bisa diatur link tujuannya masing-masing", "Kosongkan template bawaan dulu agar tidak terkunci desainnya"], "ringkasan": "Tutorial memakai page builder OrderOnline dari nol: buat halaman baru, atur untuk tampilan HP, lalu susun section satu per satu (headline, video, gambar, teks). Berbeda dengan Berdu, di sini harus buat section dulu sebelum bisa drag elemen ke dalamnya. Setiap tombol bisa diatur mengarah ke link checkout.", "langkah_praktis": ["Buka OrderOnline, buat halaman baru, kosongkan template bawaan.", "Atur mode tampilan mobile dulu (mayoritas traffic dari HP).", "Buat section satu per satu: headline, video/gambar, teks penjelas.", "Masukkan elemen ke dalam section (di OrderOnline harus buat section dulu).", "Atur setiap tombol/gambar agar mengarah ke link checkout.", "Preview di HP, klik semua tombol, pastikan tidak ada yang nyasar."]}, {"guid": "e091a373-8916-413c-bc4d-15cacc7e2490", "judul": "Membuat Landing Page dengan Weebly (Gratis)", "library": "321773", "poin_penting": ["Weebly bisa dipakai gratis dengan subdomain, cocok untuk pemula", "Hapus halaman yang tidak perlu agar fokus satu halaman saja", "Sembunyikan navigasi/header agar tidak mengalihkan perhatian", "Arahkan tombol ke link checkout lalu publish dan tes kliknya"], "ringkasan": "Tutorial membuat landing page gratis memakai Weebly: daftar akun, pilih template, pakai subdomain gratis, lalu desain dengan drag and drop tanpa coding. Halaman yang tidak perlu (seperti About dan Contact) dihapus agar hanya tersisa satu halaman fokus. Tombol diarahkan ke link checkout, lalu publish.", "langkah_praktis": ["Daftar akun Weebly gratis, pilih template sederhana.", "Hapus halaman About, Contact, dan lainnya — sisakan satu halaman saja.", "Sembunyikan navigasi/header agar pengunjung fokus.", "Susun konten dengan drag and drop: headline, gambar, tombol.", "Arahkan tombol ke link checkout-mu.", "Publish, buka link-nya dari HP, klik tombol untuk memastikan berfungsi."]}, {"guid": "e4c0b916-fc1c-441c-b669-2b4ada925795", "judul": "Setting Landing Page Single Page di Formula", "library": "321773", "poin_penting": ["Duplikasi produk dulu agar setting tidak tercampur dengan funnel lain", "Hapus pixel yang tidak relevan agar tracking bersih", "Single page = info produk dan form dalam satu halaman, cocok untuk produk simple", "Selalu verifikasi pixel lewat Event Manager setelah setting"], "ringkasan": "Cara setting landing page single page di Formula.com, yaitu info produk dan form checkout dalam satu halaman. Produk diduplikasi dulu agar tidak tercampur, lalu pixel yang tidak perlu dihapus. Setelah form diisi, pixel InitiateCheckout akan terpicu dan bisa diverifikasi lewat Event Manager.", "langkah_praktis": ["Buka Formula.com, duplikasi produk dulu agar setting tidak tercampur.", "Buat single page: info produk di atas, form checkout di bawah dalam satu halaman.", "Hapus pixel yang tidak relevan agar tracking bersih.", "Isi order percobaan lewat form.", "Buka Event Manager, pastikan event InitiateCheckout tercatat."]}, {"guid": "f338bb22-5eaa-460b-ac58-ac85be07bfc9", "judul": "Setting Checkout Page di Formula", "library": "321773", "poin_penting": ["Aktifkan WhatsApp validator atau captcha untuk menangkal fake order", "Pasang pixel AddPaymentInfo di form dan Purchase di halaman sukses", "Aktifkan server-side tracking untuk data yang lebih akurat", "Tes alur order dan pixel lewat test event sebelum iklan dijalankan"], "ringkasan": "Panduan setting checkout page di Formula.com: atur nama, harga, stok, variasi produk, dan aktifkan anti-spam. Form disederhanakan, pasang pixel AddPaymentInfo dan Purchase (server-side), atur halaman sukses, dan setting teks follow-up. Semua bisa dites lewat test event sebelum live.", "langkah_praktis": ["Buka Formula.com, atur nama produk, harga, stok, dan variasi.", "Aktifkan WhatsApp validator atau captcha untuk cegah fake order.", "Sederhanakan form, pasang pixel AddPaymentInfo.", "Pasang pixel Purchase di halaman sukses + aktifkan server-side tracking.", "Atur halaman sukses dan teks follow-up.", "Jalankan test event: buat order dummy, pastikan semua pixel terpicu sebelum iklan live."]}, {"guid": "f8f8d5cf-195b-49ff-afa6-b16c39e7100d", "judul": "Update Aturan Meta Ads untuk Landing Page (Des 2024)", "library": "321773", "poin_penting": ["Jangan pakai diskon palsu; ganti 'hari ini saja' dengan 'promo bulan ini'", "Hindari animasi berkedip dan elemen yang mengganggu pengalaman pengguna", "Jangan cantumkan angka penjualan/testimoni yang tidak bisa dibuktikan", "Hindari kata 'gratis ongkir', ganti dengan bahasa yang lebih halus"], "ringkasan": "Update penting aturan Meta Ads per Desember 2024: hindari diskon palsu untuk menciptakan urgensi, elemen animasi yang mengganggu (seperti banner berkedip), klaim yang tidak bisa diverifikasi (misalnya angka terjual yang dibuat-buat), dan kata-kata seperti gratis ongkir yang dianggap overclaim. Pelanggaran bisa membuat akun atau BM kena restrict.", "langkah_praktis": ["Buka landing page-mu, cari tulisan diskon dengan batas waktu palsu — ganti 'hari ini saja' jadi 'promo bulan ini'.", "Hapus banner/teks berkedip atau animasi yang mengganggu.", "Hapus angka penjualan/testimoni yang tidak bisa kamu buktikan.", "Ganti kata 'gratis ongkir' dengan bahasa lebih halus (misal 'bantu ongkir').", "Simpan, lalu cek ulang seluruh halaman sebelum iklan dijalankan."]}, {"guid": "6f7eb87d-1eab-4389-bacd-633276de4ebd", "library": "597307", "judul": "Cara Berjualan di AnekaDropship.id", "ringkasan": "Video ini memandu langkah demi langkah berjualan lewat AnekaDropship, mulai dari memilih 3-5 produk dan melihat marketing kit-nya, mengatur alamat supplier di Mengantar, membuat pesanan dan mencetak resi, sampai mengunggah resi dan membayar seharga modal di AnekaDropship. Di akhir juga dijelaskan cara memantau pembayaran dan memproses retur barang.", "poin_penting": ["Pilih 3-5 produk dulu dan pelajari marketing kit-nya (foto, video, spesifikasi) sebelum jualan", "Samakan alamat supplier di Mengantar dengan alamat yang tertera di detail produk AnekaDropship", "Alur pesanan: buat order di agregator, cetak resi, lalu unggah resi dan bayar seharga modal di AnekaDropship", "Pantau status di riwayat pembayaran dan riwayat pemesanan; ada panduan khusus untuk proses retur"], "langkah_praktis": ["Pilih 3-5 produk di AnekaDropship dan unduh marketing kit-nya (foto, video, spesifikasi).", "Daftar/login di anekadropship.id, catat alamat supplier tiap produk yang dipilih.", "Samakan alamat supplier di agregator (Mengantar) dengan alamat di detail produk.", "Begitu ada order: buat pesanan di agregator, cetak resi, lalu kirim barangnya.", "Unggah resi di AnekaDropship lalu bayar seharga modal produknya.", "Pantau riwayat pembayaran dan pesanan; pelajari SOP retur sebelum mulai jualan."]}, {"guid": "8ca44992-6ce0-4c1b-a1ba-3f46f74a908f", "library": "597307", "judul": "Cara Daftar AnekaDropship.id", "ringkasan": "Video ini menjelaskan cara mendaftar akun AnekaDropship dari nol: registrasi di website, lalu wajib mengisi formulir aktivasi agar mendapatkan akses gratis paket basic selama satu bulan. Setelah login, video ini juga mengenalkan satu per satu menu yang ada, seperti beranda, keranjang, wishlist, referral, kelas online, riwayat transaksi, dan permintaan marketing kit.", "poin_penting": ["Daftar di anekadropship.id lalu isi formulir aktivasi untuk klaim gratis 1 bulan paket basic", "Jangan lewatkan formulir aktivasi karena itu syarat dapat akses gratisnya", "Pelajari menu penting: detail produk (harga modal, alamat supplier), marketing kit, dan riwayat pesanan", "Manfaatkan menu kelas online dan request marketing kit untuk bahan jualan"], "langkah_praktis": ["Buka anekadropship.id, klik daftar, lalu isi data akunmu sampai selesai.", "Isi formulir aktivasi agar dapat gratis 1 bulan paket basic (jangan dilewatkan).", "Login, buka menu detail produk, catat harga modal dan alamat supplier tiap produk.", "Pelajari menu marketing kit, wishlist, dan riwayat transaksi satu per satu.", "Ikuti kelas online yang tersedia sebagai bekal sebelum mulai jualan."]}, {"guid": "f9cde8f2-b16c-48fa-b8a0-9d048177957e", "library": "597307", "judul": "Alur Gudang Online AnekaDropship", "ringkasan": "Video ini menjelaskan alur kerja jualan lewat gudang online dalam dua skema: COD dan transfer. Intinya sama: pasang iklan, terima chat pembeli, proses pesanan di agregator seperti Mengantar, cetak resi, lalu unggah resi dan beli barang seharga modal di AnekaDropship agar gudang yang mengirim ke pembeli. Uang hasil COD masuk ke akun agregator.", "poin_penting": ["Dua alur: COD (uang masuk setelah barang diterima) dan transfer (pembeli bayar dulu ke rekening penjual)", "Gunakan agregator gratis seperti Mengantar untuk mengelola pesanan dan mencetak resi", "Jangan menyetok barang sebelum ada pembeli untuk menghindari dead stock dan biaya retur", "RTS (return to seller) artinya COD gagal dan penjual menanggung ongkirnya"], "langkah_praktis": ["Tentukan dulu skemamu: COD atau transfer bank.", "Siapkan agregator gratis (Mengantar) untuk mengelola pesanan dan mencetak resi.", "Pasang iklan dan terima chat pembeli di WhatsApp seperti biasa.", "Input pesanan ke agregator, cetak resi, unggah resi lalu bayar modal di AnekaDropship agar gudang yang mengirim.", "Jangan menyetok barang sebelum ada pembeli untuk menghindari dead stock.", "Pahami risiko RTS (return to seller): ongkir retur COD gagal ditanggung penjual."]}, {"guid": "099f7a5b-d638-4e63-8ea4-86c5c41087d3", "library": "426839", "judul": "Teknik Closing via WhatsApp", "ringkasan": "Video ini mengajarkan SOP follow up chat WhatsApp agar calon pembeli yang masuk dari iklan bisa di-closing. Strateginya bertahap selama tiga hari: hari pertama langsung kirim detail produk, foto asli, dan testimoni untuk membangun kepercayaan; kalau tidak dibalas, follow up lagi di hari yang sama dan hari berikutnya; hari ketiga tawarkan diskon atau promo. Dilengkapi trik membuat foto produk asli dan video ber-voice over nama pelanggan agar lebih meyakinkan.", "poin_penting": ["Hari pertama: begitu chat masuk langsung kirim detail produk, foto asli, dan testimoni", "Buat jadwal follow up: hari ke-1 dua kali, hari ke-2 konfirmasi ulang, hari ke-3 tawarkan diskon", "Gunakan gimmick promo: diskon harga, bonus produk murah, diskon atau gratis ongkir", "Selalu kirim foto produk asli (bukan gambar editan) dan bisa tambah voice over nama pelanggan di video"], "langkah_praktis": ["Siapkan template balasan berisi detail produk, foto asli, dan testimoni.", "Begitu chat masuk di hari pertama, langsung kirim paket info tersebut.", "Kalau tidak dibalas, follow up lagi di sore hari yang sama dan keesokan paginya.", "Hari ketiga tawarkan penutup: diskon harga, bonus produk murah, atau gratis ongkir.", "Selalu kirim foto produk asli (bukan gambar editan) agar dipercaya.", "Buat video singkat dengan voice over menyebut nama pelanggan agar makin meyakinkan."]}, {"guid": "5c6fb06f-a28e-4a83-8028-b29eb59329a2", "library": "426839", "judul": "Riset Produk dengan DataPinter dan Shopee", "ringkasan": "Video ini mengajarkan riset produk di Shopee memakai tools DataPinter yang didapat gratis dari Akademi Marketer. Caranya: riset per kategori atau per produk spesifik, urutkan berdasarkan omzet 30 hari terakhir, lalu pilih produk yang murah, omzetnya naik, dan reviewnya bagus. Dilengkapi juga cara riset langsung dari menu produk terlaris di aplikasi Shopee dan cara mengambil konten iklan dari kolom testimoni.", "poin_penting": ["Manfaatkan trial DataPinter; pilih riset kategori kalau belum tahu mau jual apa, riset produk kalau sudah ada target", "Urutkan omzet 30 hari dan pilih produk murah yang grafik penjualannya naik", "Ambil konten iklan dari foto/video testimoni pembeli, lalu ganti watermark-nya", "Jangan egois pilih produk mahal; pilih yang murah, review bagus, dan lokasi toko dekat gudang"], "langkah_praktis": ["Ambil akses trial DataPinter yang disediakan Akademi Marketer.", "Pilih riset kategori kalau belum tahu mau jual apa, atau riset produk kalau sudah ada target.", "Urutkan berdasarkan omzet 30 hari terakhir; pilih produk murah yang grafik penjualannya naik.", "Cek review pembeli dan lokasi toko — yang dekat gudang lebih diutamakan.", "Ambil foto/video dari kolom testimoni untuk bahan konten, lalu ganti watermark-nya."]}, {"guid": "b4f852fc-4da7-4e11-b5a4-bf5ad814547b", "library": "426839", "judul": "Testing Konten Iklan untuk Kreator Produk Digital", "ringkasan": "Video ini mempraktikkan cara mengetes materi iklan di dashboard Meta Ads dari sudut pandang kreator produk digital. Budget disarankan separuh dari harga produk per hari, memakai conversion event satu tingkat di atas purchase agar fase pembelajaran tercapai, dan memakai Advantage+ Audience bila belum punya followers. Tiga sampai lima konten dengan angle berbeda diuji 3-7 hari, lalu yang menang dilihat dari CPC di bawah seribu dan CTR di atas satu persen sebelum di-scale up.", "poin_penting": ["Budget harian sekitar 50 persen dari harga produk; pakai event initiate checkout untuk mempercepat learning phase", "Belum punya followers: pakai Advantage+ Audience; sudah punya: retargeting custom audience followers", "Uji 3-5 konten sekaligus via quick duplicate, evaluasi minimal 3 hari (ideal 7 hari)", "Indikator konten bagus: CPC di bawah Rp1.000, CTR di atas 1%, dan cost per purchase rendah"], "langkah_praktis": ["Siapkan 3-5 konten iklan dengan angle yang berbeda-beda.", "Set budget harian sekitar 50% dari harga produk; pakai event initiate checkout agar learning phase cepat tercapai.", "Belum punya followers: pakai Advantage+ Audience. Sudah punya: pakai retargeting custom audience followers.", "Duplikat cepat (quick duplicate) lalu jalankan testing 3-7 hari.", "Evaluasi: lanjutkan konten dengan CPC di bawah Rp1.000 dan CTR di atas 1%; matikan yang boncos, scale up yang menang."]}, {"guid": "c0615fd6-2592-4d34-9c6b-32c526128bd3", "library": "426839", "judul": "Percantik Konten Iklan dengan AI dan TikTok", "ringkasan": "Video ini mengajarkan dua cara cepat membuat konten iklan yang terlihat beda: mengubah foto produk dari marketplace memakai ChatGPT agar tampak lebih elegan dan tidak pasaran, serta mengunduh video produk dari TikTok memakai SnapTik. Ditekankan pentingnya mengecek dulu seberapa banyak orang memakai gambar yang sama lewat pencarian gambar Google, dan memastikan video yang diambil tidak ada watermark agar aman dipakai beriklan.", "poin_penting": ["Cek kepasaran gambar lewat Google image search sebelum dipakai", "Minta ChatGPT membuatkan versi foto produk yang lebih elegan plus nama toko dan harga", "Unduh video TikTok via SnapTik dan pastikan tanpa watermark", "Cari produk dengan pola beli satu dapat banyak di Shopee karena marginnya menarik"], "langkah_praktis": ["Cek dulu seberapa pasaran gambarmu lewat pencarian gambar Google.", "Minta ChatGPT membuatkan versi foto produk yang lebih elegan, sekalian tambah nama toko dan harga.", "Cari video produk di TikTok, unduh via SnapTik, pastikan tidak ada watermark.", "Pilih produk berpola beli satu dapat banyak di Shopee karena marginnya menarik.", "Pakai konten yang sudah dipercantik ini sebagai bahan iklanmu."]}, {"guid": "f6a25ab6-ceda-42e2-a94f-3aeea53c6adb", "library": "426839", "judul": "Riset Produk Lewat Ad Library", "ringkasan": "Video ini mengajarkan riset produk dengan memanfaatkan Ad Library milik Meta. Triknya: cari iklan yang diduplikasi belasan hingga puluhan kali karena itu tanda produknya sedang laku dan di-scale up, gunakan Ctrl+F untuk memfilter cepat. Setelah ketemu produknya, cek harga di marketplace, hitung marginnya, pastikan supplier dekat gudang, lalu unduh konten iklannya lewat inspect element untuk dijadikan bahan.", "poin_penting": ["Fokus pada iklan yang diduplikasi 10x atau lebih sebagai tanda produk winning", "Pakai trik Ctrl+F kata ads untuk menemukan produk ramai dengan cepat", "Hitung margin: harga jual iklan dikurangi harga modal harus cukup tebal", "Ambil konten iklan via inspect element di Chrome, lalu edit sedikit dan ganti watermark"], "langkah_praktis": ["Buka Ad Library milik Meta, lalu cari dengan kata kunci produk.", "Tekan Ctrl+F untuk memfilter cepat; fokus pada iklan yang diduplikasi 10x atau lebih sebagai tanda produk winning.", "Cek harga produknya di marketplace lalu hitung margin: harga jual iklan dikurangi harga modal.", "Pastikan supplier dekat dengan gudang agar ongkir dan pengiriman aman.", "Unduh konten iklannya via inspect element di Chrome, edit sedikit, lalu ganti watermark."]}, {"guid": "fc5a4e90-4cf2-4806-a1e8-44868c6619a4", "library": "426839", "judul": "Membuat Halaman Checkout di Mengantar", "ringkasan": "Video ini memandu membuat halaman checkout di Mengantar (Formula.com) untuk menghitung ongkir dan mencatat pesanan dari chat WhatsApp. Langkahnya: tambah produk fisik, isi harga jual yang sama dengan harga di iklan, nyalakan pengaturan pengiriman dengan alamat gudang, aktifkan pembayaran COD dan transfer, lalu atur formulir pemesanan. Halaman ini yang diisi penjual saat pembeli bertanya ongkir, jadi tidak perlu buka website ekspedisi satu per satu.", "poin_penting": ["Harga jual di checkout harus sama persis dengan harga di iklan agar tidak rugi", "Gunakan alamat gudang sebagai alamat pengirim, bukan alamat supplier langsung", "Aktifkan COD dan transfer bank; centang field nama, no HP, alamat lengkap, dan jumlah pesanan", "Siapkan minimal 5 produk di checkout sebelum mulai testing iklan"], "langkah_praktis": ["Login ke Mengantar (Formula.com), lalu tambah produk fisik baru.", "Isi harga jual SAMA PERSIS dengan harga yang tertera di iklan agar tidak rugi.", "Isi alamat gudang sebagai alamat pengirim; nyalakan pengaturan pengiriman.", "Aktifkan metode pembayaran COD dan transfer bank.", "Atur field formulir: nama, nomor HP, alamat lengkap, dan jumlah pesanan wajib dicentang.", "Siapkan minimal 5 produk di halaman checkout sebelum mulai testing iklan."]}, {"guid": "302c1de2-7964-40f4-b19c-dcb36bbde2a0", "library": "367001", "judul": "Riset Produk Digital yang Laris", "ringkasan": "Video ini menjelaskan cara menemukan produk digital yang berpotensi laku. Diawali dengan pengenalan jenis-jenis produk digital dan perbedaan lisensi PLR (boleh diubah dan diklaim sebagai karya sendiri) dengan MRR (hanya boleh dijual ulang). Praktiknya memakai Etsy: cari dengan kata kunci, nilai dari rating, jumlah terjual, dan tampilannya, lalu catat di worksheet dan validasi ulang lewat Ad Library sebelum dibeli dan dijual kembali.", "poin_penting": ["Kenali jenis produk digital: ebook, kelas online, template, tools, audio, membership", "Pahami lisensi: PLR boleh di-rebranding, MRR hanya boleh dijual ulang apa adanya", "Riset di Etsy dengan indikator rating bagus, sudah banyak terjual, dan visual proper", "Untuk pecah telor, pilih produk di bawah Rp100 ribu agar pembeli mudah mengeluarkan uang"], "langkah_praktis": ["Tentukan dulu jenis produk digital yang mau dijual: ebook, template, kelas online, tools, atau lainnya.", "Pahami lisensinya: PLR boleh diubah dan diklaim sebagai karya sendiri, MRR hanya boleh dijual ulang apa adanya.", "Riset di Etsy: cari dengan kata kunci, nilai dari rating, jumlah terjual, dan tampilannya.", "Catat kandidat produk di worksheet lalu validasi ulang lewat Ad Library.", "Untuk pecah telor, pilih produk di bawah Rp100 ribu agar pembeli mudah mengeluarkan uang."]}, {"guid": "69db3e60-b051-49db-804c-ae2c2d6660a5", "library": "367001", "judul": "Riset Konten Iklan Produk Digital", "ringkasan": "Video ini mengajarkan cara meriset konten iklan kompetitor untuk produk digital memakai Ad Library. Setiap temuan dicatat di worksheet berisi link iklan, tipe konten, angle, dan pesannya. Contohnya angle yang menyoroti masalah (gaji habis tiap akhir bulan) lengkap dengan pain point dan solusinya. Setelah terkumpul 5 contoh, peserta membuat versinya sendiri memakai Canva, CapCut, atau bantuan AI.", "poin_penting": ["Kumpulkan minimal 5 contoh iklan kompetitor dari Ad Library ke dalam worksheet", "Bedah tiap iklan: tipe kontennya apa, angle-nya apa, pesannya apa", "Angle yang kuat biasanya menyoroti masalah nyata plus solusinya", "Buat ulang dengan gayamu sendiri memakai Canva, CapCut, atau prompt AI"], "langkah_praktis": ["Buka Ad Library, cari iklan kompetitor produk digital yang sejenis dengan rencanamu.", "Kumpulkan minimal 5 contoh ke dalam worksheet berisi link iklan, tipe konten, angle, dan pesannya.", "Bedah tiap iklan: angle masalahnya apa dan solusi apa yang ditawarkan.", "Buat ulang versimu sendiri dengan gayamu memakai Canva, CapCut, atau bantuan prompt AI.", "Pastikan kontenmu orisinal, jangan jiplak mentah-mentah."]}, {"guid": "9b5e1dbe-326f-45ca-90a0-734c0882d7f6", "library": "367001", "judul": "Membedah Landing Page Kompetitor", "ringkasan": "Video ini mengajarkan cara membedah landing page kompetitor agar bisa membuat halaman jualan yang konversinya tinggi. Caranya: temukan iklan di Ad Library, buka landing page-nya, lalu catat elemen-elemennya ke worksheet mulai dari headline, visual, manfaat produk, bukti testimoni, hingga urgensi promonya. Tujuannya agar peserta paham pola landing page yang proper sebelum membuat milik sendiri di Scalev atau platform sejenis.", "poin_penting": ["Bedah minimal beberapa landing page kompetitor sebelum membuat milikmu", "Catat elemen kunci: headline, sub-headline, visual, CTA, benefit, testimoni, urgensi", "Perhatikan gaya bahasa dan desain: yang konversi tinggi biasanya personal, bersih, dan CTA-nya jelas", "Gabungkan pola terbaik jadi satu landing page versi kamu"], "langkah_praktis": ["Temukan iklan kompetitor di Ad Library, lalu buka landing page yang ditautkan.", "Catat elemen-elemennya ke worksheet: headline, sub-headline, visual, CTA, benefit, testimoni, dan urgensi promo.", "Perhatikan gaya bahasa dan desainnya — yang konversi tinggi biasanya personal, bersih, dan CTA-nya jelas.", "Ulangi untuk beberapa kompetitor sampai polanya terlihat.", "Gabungkan pola terbaik menjadi satu landing page versimu di Scalev atau platform sejenis."]}, {"guid": "a7a3e2d5-84e9-4ccb-84f9-728900d8ea49", "library": "367001", "judul": "Beriklan Produk Digital di Meta Ads", "ringkasan": "Video ini mempraktikkan langkah demi langkah membuat kampanye iklan produk digital di Meta Ads memakai struktur 1-1-5: satu campaign, satu ad set, lima konten iklan. Budget harian 50-75 ribu memakai campaign budget, audience dibiarkan broad, lokasi Indonesia, dan jadwal tayang diatur besok pagi agar semua konten selesai direview berbarengan. Copywriting dibantu ChatGPT dan tombol aksinya memakai Order Now.", "poin_penting": ["Struktur 1-1-5: 1 campaign, 1 ad set, 5 konten iklan berbeda", "Budget 50-75 ribu per hari; jadwalkan tayang besok pagi agar review-nya bareng", "Biarkan audience broad (Advantage+) kecuali sudah yakin marketnya spesifik", "Pastikan Fanpage, Instagram, dan pixel sudah terhubung sebelum publish"], "langkah_praktis": ["Pastikan Fanpage, akun Instagram, dan pixel sudah saling terhubung sebelum mulai.", "Buat campaign baru dengan struktur 1-1-5: 1 campaign, 1 ad set, 5 konten iklan berbeda.", "Set budget 50-75 ribu per hari memakai campaign budget; biarkan audience broad (Advantage+).", "Set lokasi Indonesia dan jadwalkan tayang besok pagi agar semua konten selesai direview berbarengan.", "Minta ChatGPT membantu merapikan copywriting; pakai tombol aksi Order Now.", "Publish lalu pantau 2-3 hari sebelum mengambil keputusan."]}, {"guid": "aec67521-11b2-4ace-bdc4-543015993ca5", "library": "367001", "judul": "Menghubungkan Fanpage ke Instagram", "ringkasan": "Video singkat ini menunjukkan cara menautkan Fanpage Facebook dengan akun Instagram agar bisa dipakai beriklan. Caranya: buka Fanpage, masuk ke pengaturan, pilih menu linked accounts, pilih Instagram, lalu login. Catatannya, bila akun Instagram sudah tertaut ke Fanpage lain, harus diputus dulu dari sisi Instagram sebelum bisa ditautkan ke yang baru.", "poin_penting": ["Buka Fanpage lalu ke Settings dan pilih Linked Accounts", "Pilih Instagram dan login dengan akun yang mau dipakai iklan", "Pastikan koneksinya muncul otomatis saat setting iklan nanti", "Kalau gagal, cek apakah IG-nya masih tertaut ke Fanpage lain"], "langkah_praktis": ["Buka Fanpage Facebook milikmu, lalu masuk ke menu Settings.", "Pilih Linked Accounts, lalu pilih Instagram.", "Login dengan akun Instagram yang mau dipakai untuk beriklan.", "Pastikan koneksinya muncul otomatis saat kamu setting iklan nanti.", "Kalau gagal tertaut, cek apakah IG tersebut masih tertaut ke Fanpage lain — putus dulu dari sisi Instagram."]}, {"guid": "c27068a2-f18d-48d7-8d3e-68214fcfdf2e", "library": "367001", "judul": "Tools Validasi Ide Bisnis dengan AI", "ringkasan": "Video ini mengenalkan tools gratis bernama Idea Pro Marketer untuk memvalidasi ide bisnis sebelum dieksekusi. Cara pakainya: pilih kategori bisnis dan mode cepat atau lengkap, pilih jenis analisis yang dibutuhkan (misalnya business validator atau STP analysis), isi form tentang produk dan target pasar, lalu salin prompt yang dihasilkan ke ChatGPT atau Gemini untuk mendapatkan laporan analisis lengkap dalam hitungan menit.", "poin_penting": ["Gunakan mode cepat untuk produk fisik yang harus segera dites, mode lengkap untuk produk digital", "Semakin detail jawaban di form, semakin tajam analisis AI-nya", "Hasilnya bisa membedakan apakah ide termasuk red ocean atau masih blue ocean", "Jadikan sebagai saringan awal sebelum konsultasi ke mentor"], "langkah_praktis": ["Buka tools gratis Idea Pro Marketer.", "Pilih kategori bisnismu dan mode analisis: cepat untuk produk fisik, lengkap untuk produk digital.", "Pilih jenis analisis yang dibutuhkan, misalnya business validator atau STP analysis.", "Isi form tentang produk dan target pasarmu sedetail mungkin — makin detail makin tajam hasilnya.", "Salin prompt yang dihasilkan ke ChatGPT atau Gemini untuk mendapatkan laporan analisis lengkap.", "Jadikan hasilnya sebagai saringan awal sebelum konsultasi ke mentor."]}, {"guid": "f0a07f40-ac62-413f-8e66-00a8c887ed92", "library": "367001", "judul": "Membaca Data Iklan dan Evaluasi CTWA", "ringkasan": "Video ini mengajarkan cara membaca data iklan CTWA dan mengambil keputusan. Atur dulu kolom dashboard berisi CPC, CPM, CTR, dan cost per result. Patokannya: CPC di bawah seribu, CPM di bawah dua puluh ribu, CTR di atas dua persen, dan biaya per chat di bawah dua ribu. Evaluasi bisa dimulai setelah spend 10-15 ribu, jangan tunggu habis ratusan ribu. Ada juga trik membuat rule otomatis yang mematikan iklan setiap spend menyentuh lima ribu agar mudah dievaluasi.", "poin_penting": ["Evaluasi setelah spend Rp10-15 ribu; jangan tunggu boncos ratusan ribu", "Matikan konten yang CPC dan biaya per chat-nya mahal; lanjutkan yang sesuai KPI", "Buat rule otomatis: spend di atas Rp5.000 iklan mati untuk dievaluasi", "Kalau closing-nya gampang, KPI boleh diabaikan karena ujungnya tetap cuan"], "langkah_praktis": ["Atur kolom dashboard iklan agar menampilkan CPC, CPM, CTR, dan cost per result.", "Jalankan iklan, lalu mulai evaluasi setelah spend Rp10-15 ribu — jangan tunggu boncos ratusan ribu.", "Patokannya: CPC di bawah Rp1.000, CPM di bawah Rp20 ribu, CTR di atas 2%, biaya per chat di bawah Rp2.000.", "Matikan konten yang CPC dan biaya per chat-nya mahal; lanjutkan yang sesuai KPI.", "Buat rule otomatis: setiap spend menyentuh Rp5.000 iklan mati agar mudah dievaluasi."]}, {"guid": "fdbcc309-18ce-4376-92bd-e79aa3026ebd", "library": "367001", "judul": "Riset Niche untuk Produk Digital", "ringkasan": "Video ini menjelaskan cara menemukan niche yang tepat untuk produk digital. Rumusnya: masalah yang spesifik ditambah solusi yang unik menghasilkan niche emas. Niche yang tidak lekang waktu adalah seputar wealth, health, dan relationship. Makin spesifik niche-nya makin kecil saingannya, tapi pastikan tetap ada permintaan pasar. Cara risetnya lewat Instagram: cari akun dengan followers 30-100 ribu, engagement bagus, dan sudah menjual produk digital.", "poin_penting": ["Gunakan rumus masalah spesifik plus solusi unik untuk menemukan niche", "Fokus ke niche evergreen: wealth, health, relationship", "Validasi niche lewat Instagram: followers 30-100rb, engagement hidup, jual produk digital", "Catat 5 kompetitor se-niche beserta masalah dan solusi yang mereka tawarkan"], "langkah_praktis": ["Terapkan rumus niche: masalah yang spesifik ditambah solusi yang unik.", "Fokus ke niche yang tidak lekang waktu: wealth, health, atau relationship.", "Riset di Instagram: cari akun dengan 30-100 ribu followers, engagement bagus, dan sudah menjual produk digital.", "Catat 5 kompetitor se-niche beserta masalah dan solusi yang mereka tawarkan.", "Pilih niche yang spesifik (saingan kecil) tapi pastikan tetap ada permintaan pasar."]}, {"guid": "07e2fb98-1f65-4337-b341-f30f4c6948a6", "library": "367194", "judul": "Sambutan Kelas Launching Produk Digital", "ringkasan": "Video pembuka ini memperkenalkan mentor Aditya yang sudah 11 tahun meluncurkan produk digital dan menjadi super affiliate. Ia memaparkan garis besar materi kelas: pengertian produk digital, alasan memilihnya, jenis lisensi, repackaging, cara jualan tanpa website dan tanpa media sosial, sampai pembuatan website, sistem jualan, dan sistem afiliasi. Intinya, produk digital disebut sebagai salah satu peluang terbesar untuk mendapatkan penghasilan aktif maupun pasif di era internet.", "poin_penting": ["Kenali dulu siapa mentor dan rekam jejaknya sebelum mengikuti kelas", "Pahami peta materi dari hulu (pengertian) sampai hilir (sistem afiliasi)", "Produk digital diposisikan sebagai peluang income aktif dan pasif", "Ikuti videonya berurutan agar tiap materi saling nyambung"], "langkah_praktis": ["Kenali dulu siapa mentor kelasnya dan rekam jejaknya sebelum mulai.", "Baca peta materi dari awal sampai akhir agar paham alurnya: pengertian, lisensi, repackaging, sistem jualan, afiliasi.", "Tonton videonya berurutan agar tiap materi saling nyambung.", "Siapkan mindset bahwa produk digital bisa jadi income aktif maupun pasif."]}, {"guid": "2374dd64-9b0e-43de-bec6-be7d6c542a6a", "library": "367194", "judul": "Kenapa Harus Jualan Produk Digital", "ringkasan": "Video ini menjawab dengan tiga alasan objektif kenapa produk digital layak dipilih. Pertama, biaya produksinya murah: buat sekali, jual berkali-kali tanpa perlu produksi ulang seperti produk fisik. Kedua, tidak ada kadaluarsa: produk yang dibuat tahun 2013 masih bisa dijual tahun 2025. Ketiga, sifatnya fleksibel dan tanpa batas: ilmu atau aset yang sama bisa dipakai ulang untuk produk, waktu, dan pasar yang berbeda.", "poin_penting": ["Produksi sekali, jual berkali-kali sehingga marginnya besar", "Tidak ada stok, tidak basi, dan tidak ada biaya produksi ulang", "Satu skill atau aset bisa dipakai untuk banyak produk berbeda", "Cocok untuk membangun penghasilan pasif jangka panjang"], "langkah_praktis": ["Pahami tiga alasan objektifnya: produksi sekali jual berkali-kali, tidak ada kadaluarsa, fleksibel dipakai ulang.", "Pilih satu skill atau aset yang kamu kuasai untuk dijadikan produk digital pertama.", "Hitung marginnya: tanpa stok dan biaya produksi ulang, margin jauh lebih besar dari produk fisik.", "Jadikan produk digital sebagai fondasi penghasilan pasif jangka panjangmu."]}, {"guid": "50cbe01e-c33f-4f6c-b6df-3cdcbf89de14", "library": "367194", "judul": "Mengenal Macam-macam Produk Digital", "ringkasan": "Video ini menguraikan definisi dan jenis-jenis produk digital. Ciri khas utamanya cuma satu: tidak ada fisiknya, tapi manfaatnya bisa dirasakan. Jenisnya sangat luas: kelas online (video on demand, webinar, mentoring), software (SaaS, desktop, tools WordPress, aplikasi mobile), desain grafis (template media sosial, banner, video), sampai produk era AI seperti kumpulan prompt, dan artikel.", "poin_penting": ["Ciri mutlak produk digital: tanpa fisik tapi manfaatnya nyata", "Jangan mengira produk digital hanya kelas online; jenisnya sangat banyak", "Software terbagi lagi: SaaS, desktop, plugin/theme WordPress, aplikasi mobile", "Produk baru bermunculan mengikuti tren, misalnya prompt AI"], "langkah_praktis": ["Pelajari jenis-jenisnya: kelas online, software (SaaS/desktop/plugin), desain grafis, template, prompt AI, artikel.", "Jangan terpaku bahwa produk digital hanya kelas online — jenisnya sangat luas.", "Pilih jenis produk yang sesuai dengan skill dan resources yang kamu punya sekarang.", "Amati tren baru seperti prompt AI sebagai peluang produk berikutnya."]}, {"guid": "6828bfdd-37f5-4096-864a-95b3366acf05", "library": "367194", "judul": "Membuat Sistem Afiliasi Produk Digital", "ringkasan": "Video ini menjelaskan cara membangun sistem afiliasi agar produk digital dipromosikan banyak orang. Alurnya: vendor membuat produk dan menentukan komisi, afiliat mempromosikan lewat link uniknya, dan setiap penjualan lewat link itu menghasilkan komisi. Praktiknya memakai plugin Sejoli di WordPress: aktifkan fitur afiliasi per produk, atur besaran komisi (nominal atau persen), lalu sediakan materi promosi. Sistem ini juga bisa dipakai untuk mengadakan kontes afiliasi.", "poin_penting": ["Tentukan komisi yang menarik, bisa nominal tetap atau persen (misal 30-50%)", "Aktifkan fitur afiliasi per produk di sistem membership seperti Sejoli", "Sediakan link unik, banner, dan materi promosi untuk para afiliat", "Adakan kontes afiliasi 7-14 hari untuk mendongkrak penjualan"], "langkah_praktis": ["Install plugin Sejoli di WordPress, lalu aktifkan fitur afiliasi untuk tiap produk.", "Tentukan komisi yang menarik: nominal tetap atau persen (misalnya 30-50%).", "Siapkan link unik, banner, dan materi promosi untuk para afiliat.", "Rekrut afiliat dan sediakan grup atau materi pendukung agar mereka mudah promosi.", "Adakan kontes afiliasi 7-14 hari untuk mendongkrak penjualan.", "Pantau performa tiap afiliat dan beri reward ke yang terbaik."]}, {"guid": "7e316a70-9312-4238-b207-1444192cfcb4", "library": "367194", "judul": "Jualan Produk Digital Tanpa Bergantung Media Sosial", "ringkasan": "Video ini menunjukkan empat jalur jualan produk digital tanpa mengandalkan media sosial untuk direct selling. Pertama, email marketing dengan database dari pembeli dan lead magnet berupa produk gratis. Kedua, SEO lewat artikel blog yang mengarah ke halaman jualan. Ketiga, beriklan berbayar di Meta, TikTok, atau Google. Keempat, affiliate traffic lewat kontes afiliasi. Media sosial tetap boleh punya, tapi fungsinya untuk kehidupan personal bukan jualan langsung.", "poin_penting": ["Bangun database email dari pembeli dan dari lead magnet gratis", "Tulis artikel SEO yang mengarah ke halaman penjualan", "Alokasikan budget iklan berbayar sebagai salah satu jalur traffic", "Jalankan kontes afiliasi agar orang lain yang mempromosikan produkmu"], "langkah_praktis": ["Kumpulkan database email dari pembeli yang sudah ada dan dari lead magnet berupa produk gratis.", "Tulis artikel blog yang dioptimasi SEO dan arahkan pembacanya ke halaman penjualan.", "Alokasikan budget untuk iklan berbayar di Meta, TikTok, atau Google sebagai salah satu jalur traffic.", "Jalankan kontes afiliasi agar orang lain yang mempromosikan produkmu.", "Media sosial tetap boleh dipakai, tapi fungsinya untuk personal branding bukan jualan langsung."]}, {"guid": "7e76bba7-4d84-4b4f-91e2-bc6b6e6b5cd1", "library": "367194", "judul": "Jualan Produk Digital Tanpa Website", "ringkasan": "Video ini memberi dua solusi bagi yang tidak mau repot membuat website. Pertama, manfaatkan fasilitas dari vendor produknya: biasanya penjual lisensi resell menyediakan akses reseller atau generator landing page siap pakai. Kedua, gunakan tools gratis seperti Mayar.id yang bisa membuat landing page dengan sistem drag-and-drop lengkap dengan template. Intinya, tidak punya website bukan alasan untuk tidak mulai jualan.", "poin_penting": ["Tanyakan ke vendor apakah tersedia reseller access atau landing page generator", "Alternatif gratis: buat landing page di Mayar.id dengan drag-and-drop", "Fokus pada fungsi jualan, bukan sekadar tampilan yang keren", "Website bisa menyusul belakangan setelah ada pemasukan"], "langkah_praktis": ["Tanyakan ke vendor produk: apakah tersedia akses reseller atau generator landing page siap pakai.", "Kalau tidak ada, buat landing page gratis di Mayar.id dengan sistem drag-and-drop.", "Fokus pada fungsi jualan (CTA jelas, info lengkap), bukan sekadar tampilan yang keren.", "Mulai jualan dulu dengan cara ini; website proper bisa menyusul setelah ada pemasukan."]}, {"guid": "96f19732-954c-4b5f-b7f5-cde588eee61e", "library": "367194", "judul": "Memahami Lisensi Produk Digital", "ringkasan": "Video ini mengupas tuntas jenis-jenis lisensi produk digital yang wajib dipahami sebelum menjual ulang. Aturan bakunya hanya dua: personal use (hanya untuk dipakai sendiri) dan commercial use (boleh dipakai untuk kebutuhan komersial). Untuk kebutuhan jualan dikenal istilah resell rights (jual ulang, 100 persen profit, tidak boleh klaim sebagai karya sendiri), master resell rights, private label rights atau PLR (boleh diubah dan diklaim sebagai karya sendiri), hingga white label sebagai tingkatan tertinggi.", "poin_penting": ["Bedakan personal use dengan commercial use sebelum memakai produk orang", "Resell rights: boleh jual ulang tapi tidak boleh klaim sebagai buatanmu", "PLR: boleh edit, ganti nama, dan klaim sebagai produk sendiri", "Selalu baca aturan lisensi dari kreatornya karena tiap kreator bisa beda istilah"], "langkah_praktis": ["Bedakan dulu dua aturan baku: personal use (dipakai sendiri) vs commercial use (boleh untuk komersial).", "Pelajari tingkatannya: resell rights, master resell rights, PLR, sampai white label.", "Selalu baca aturan lisensi dari kreatornya karena tiap kreator bisa memakai istilah berbeda.", "Pilih lisensi sesuai rencanamu: mau rebrand dan klaim sebagai milikmu pilih PLR; mau jual apa adanya pilih resell/MRR.", "Jangan pernah melanggar aturan lisensi agar tidak kena masalah di kemudian hari."]}, {"guid": "b12a4d57-2a3f-46e9-804b-29ef8313c3cf", "library": "367194", "judul": "Repackaging Produk Digital Siap Jual", "ringkasan": "Video ini mempraktikkan proses repackaging: mengubah produk digital berlisensi menjadi produk siap jual atas nama sendiri. Langkahnya: buat cover box dengan template mockup gratis yang diedit di Canva lalu dipasang via Photoshop atau Photopea, lalu buat landing page dengan memanfaatkan template JSON dari marketing kit vendor yang diimpor ke Elementor. Terakhir tinggal datangkan traffic lewat iklan atau media sosial.", "poin_penting": ["Cari template mockup box gratis lalu desain cover di Canva sesuai ukuran kanvasnya", "Manfaatkan template landing page dari marketing kit vendor, tinggal impor", "Ganti nama produk, video, dan link tombol sesuai branding-mu", "Tidak perlu membuat produk dari nol bila lisensinya mengizinkan"], "langkah_praktis": ["Cari template mockup box gratis yang sesuai, lalu desain cover produkmu di Canva mengikuti ukurannya.", "Pasang cover tersebut memakai Photoshop atau Photopea (gratis).", "Minta template landing page (format JSON) dari marketing kit vendor, lalu impor ke Elementor.", "Ganti nama produk, video, dan link tombol sesuai branding-mu sendiri.", "Datangkan traffic ke landing page lewat iklan atau media sosial."]}, {"guid": "d8b3c588-52ea-4894-9fdf-1b337ba14297", "library": "367194", "judul": "Membuat Website Jualan dengan WordPress", "ringkasan": "Video ini memandu membuat website jualan dari nol memakai WordPress. Kebutuhannya hanya domain dan hosting, lalu install WordPress otomatis lewat Softaculous di cPanel. Setelah itu atur dasar seperti zona waktu dan permalink, install plugin penting (Jetpack, Akismet, Elementor), lalu buat halaman penjualan dengan Elementor yang tinggal drag-and-drop dan sudah tersedia template. Kalau membeli produk resell, template landing page-nya biasanya sudah disediakan vendor.", "poin_penting": ["Siapkan domain dan hosting, lalu install WordPress via Softaculous", "Atur timezone Asia/Jakarta dan permalink model post name", "Install plugin: Jetpack (performa), Akismet (anti-spam), Elementor (page builder)", "Buat landing page dengan Elementor tanpa perlu bisa coding"], "langkah_praktis": ["Beli domain dan hosting, lalu install WordPress otomatis via Softaculous di cPanel.", "Atur dasar: timezone Asia/Jakarta dan permalink model post name.", "Install plugin penting: Jetpack (performa), Akismet (anti-spam), dan Elementor (page builder).", "Buat halaman penjualan dengan Elementor secara drag-and-drop memakai template yang tersedia.", "Kalau membeli produk resell, pakai template landing page yang biasanya sudah disediakan vendor."]}, {"guid": "f158c7af-f141-4456-b17f-bb6601ba70f3", "library": "367194", "judul": "Jalan Pintas Membuat Produk Digital", "ringkasan": "Video ini membandingkan dua jalan membuat produk digital. Jalan normal: riset produk, lalu development yang bisa makan waktu 60-180 hari, baru jualan dengan hasil yang belum pasti. Jalan pintas: beli produk digital yang lisensinya memang mengizinkan untuk dijual ulang, sehingga dapat 100 persen profit dan boleh diklaim sebagai produk sendiri, bahkan boleh digratiskan atau dijadikan bonus. Rekomendasinya jelas memakai jalan pintas selama lisensinya memang mengizinkan.", "poin_penting": ["Jalan normal butuh riset plus development berbulan-bulan dengan hasil belum pasti", "Jalan pintas: beli lisensi resell/PLR, langsung jual dan dapat 100 persen profit", "Pastikan lisensinya memang mengizinkan dijual ulang; jangan langgar aturan kreator", "Hemat waktu, tenaga, dan biaya dengan memanfaatkan produk yang sudah jadi"], "langkah_praktis": ["Tentukan niche dan jenis produk digital yang mau kamu jual.", "Cari produk berlisensi resell atau PLR yang sesuai dengan niche tersebut.", "Baca aturan lisensinya dengan teliti — pastikan memang mengizinkan dijual ulang.", "Beli lisensinya, rebrand bila diizinkan, lalu langsung jual dan dapatkan 100% profit.", "Hemat waktu development berbulan-bulan dengan memanfaatkan produk yang sudah jadi ini."]}, {"guid": "febfc883-0902-4149-b2f2-f0be07a953a3", "library": "367194", "judul": "Membuat Sistem Penjualan dengan Sejoli", "ringkasan": "Video ini mempraktikkan pembuatan sistem penjualan otomatis memakai plugin Sejoli di WordPress. Setelah beli lisensi dan install plugin, tinggal buat produk, aktifkan status jual, dan isi harga, maka langsung jadi link checkout tempat pembeli mengisi data dan membayar. Sistem ini bisa dihubungkan ke payment gateway lokal dan sudah termasuk fitur membership serta afiliasi, sehingga wajib dimiliki siapa pun yang serius jualan produk digital.", "poin_penting": ["Beli dan install plugin Sejoli, lalu masukkan kode lisensinya", "Buat produk, isi harga, publish, maka link checkout langsung jadi", "Hubungkan ke payment gateway seperti Duitku atau transfer bank", "Sistem ini sekaligus menyediakan member area dan sistem afiliasi"], "langkah_praktis": ["Beli lisensi Sejoli, install plugin-nya di WordPress, lalu masukkan kode lisensi.", "Buat produk baru: isi nama dan harga, aktifkan status jual, lalu publish.", "Salin link checkout yang otomatis terbentuk setelah produk dipublish.", "Hubungkan ke payment gateway lokal seperti Duitku atau transfer bank.", "Manfaatkan fitur membership untuk area member dan fitur afiliasi yang sudah termasuk."]}, {"guid": "4f63d4c7-4f7f-4530-9751-3ac3979872db", "library": "457137", "judul": "Cara Cepat Membuat Produk Digital", "ringkasan": "Video ini merangkum alur cepat membuat dan menjual produk digital. Alur jualannya terdiri dari tiga elemen: platform order seperti Scalev atau Linkit, media sosial untuk branding, dan WhatsApp untuk pengiriman produk. Tools wajibnya adalah ChatGPT, Instagram, dan WhatsApp, ditambah Canva dan CapCut sebagai pendukung. Untuk platform jualan, Scalev unggul di kecepatan sedangkan Linkit unggul di kemudahan pakai.", "poin_penting": ["Siapkan tiga elemen: platform order, sosmed untuk branding, WhatsApp untuk delivery", "Tools inti: ChatGPT untuk isi, Instagram untuk branding, WhatsApp untuk jualan", "Tools pendukung: Canva untuk desain, CapCut untuk video", "Pilih Scalev untuk kecepatan atau Linkit untuk kemudahan"], "langkah_praktis": ["Siapkan tiga elemen jualan: platform order (Scalev/Linkit), media sosial untuk branding, WhatsApp untuk pengiriman produk.", "Install tools inti: ChatGPT untuk membuat isi, Instagram untuk branding, WhatsApp untuk jualan.", "Tambahkan tools pendukung: Canva untuk desain dan CapCut untuk video.", "Pilih platform jualan: Scalev kalau butuh kecepatan, Linkit kalau butuh kemudahan pakai.", "Buat atau siapkan produk digitalmu, pasang di platform order, lalu mulai terima pesanan."]}, {"guid": "542840f4-6b6f-4463-a954-8891ed2f7879", "library": "457137", "judul": "Facebook Pixel: Pengertian dan Cara Membuat", "ringkasan": "Video ini menjelaskan Facebook Pixel sebagai alat pencatat aktivitas pengunjung website, dari masuk landing page sampai checkout dan purchase. Tanpa pixel, pengiklan tidak bisa tahu iklan mana yang menghasilkan penjualan terbanyak. Cara membuatnya: buka Business Settings, masuk ke Data Sources lalu Datasets, buat dataset baru dan hubungkan ke akun iklan, kemudian buat access token di Events Manager untuk dipasang di website.", "poin_penting": ["Pixel mencatat perjalanan pengunjung: view, isi form, sampai beli", "Tanpa pixel, evaluasi iklan hanya tebak-tebakan", "Buat dataset di Business Settings lalu hubungkan ke akun iklan", "Simpan ID pixel dan access token untuk dipasang di landing page"], "langkah_praktis": ["Buka Business Settings, masuk ke menu Data Sources lalu Datasets.", "Buat dataset baru dan beri nama sesuai bisnismu.", "Hubungkan dataset tersebut ke akun iklan yang dipakai.", "Buka Events Manager lalu buat access token untuk dataset itu.", "Pasang ID pixel dan access token di landing page/websitemu.", "Verifikasi pemasangannya memakai ekstensi Meta Pixel Helper di Chrome."]}, {"guid": "66035f0b-5ee7-4f6f-ab69-d4556e405552", "library": "457137", "judul": "Mendesain Ebook Cantik dengan Canva", "ringkasan": "Video ini mengajarkan cara membuat tampilan ebook terlihat profesional memakai Canva tanpa perlu keahlian desain. Kuncinya: pilih template yang simpel dan bersih, tata isi per bab dengan satu halaman satu subjudul dan maksimal 3-5 paragraf, pakai font yang mudah dibaca, batasi warna pada 2-3 warna dominan, tambah ikon agar tidak membosankan, lalu ekspor sebagai PDF siap jual.", "poin_penting": ["Pilih template minimalis: putih bersih, font terbaca, layout longgar", "Satu halaman satu subjudul; pakai bullet, numbering, atau emoji sebagai variasi", "Font judul 24-32 (misal Anton/Poppins Bold), font isi 14-16 (misal Inter/Open Sans)", "Batasi 2-3 warna lalu ekspor ke PDF"], "langkah_praktis": ["Buka Canva lalu pilih template ebook yang simpel dan bersih.", "Susun isi per bab: satu halaman satu subjudul dengan maksimal 3-5 paragraf.", "Pakai font judul ukuran 24-32 (misal Anton/Poppins Bold) dan font isi 14-16 (misal Inter/Open Sans).", "Batasi warna pada 2-3 warna dominan; tambah ikon agar halaman tidak membosankan.", "Variasikan dengan bullet, numbering, atau emoji secukupnya.", "Ekspor sebagai PDF agar siap dijual."]}, {"guid": "79384af6-2fe2-42f0-9053-a6c2e98c8d18", "library": "457137", "judul": "Strategi Branding Instagram 8 Hari", "ringkasan": "Video ini menyusun rencana 8 hari membangun akun Instagram untuk branding produk digital. Idenya: akun organik butuh waktu lama, sedangkan strategi ini mempercepat dengan optimasi tampilan agar terlihat kredibel. Hari pertama sampai kelima dipakai untuk menyiapkan akun, riset konten, membuat produk, dan menyiapkan platform jualan tanpa posting dulu. Hari keenam optimasi tampilan, hari ketujuh mulai posting rutin 1-3 kali sehari, hari kedelapan evaluasi lewat insight.", "poin_penting": ["Siapkan dulu akun, produk, dan platform sebelum mulai posting", "Riset konten viral se-niche lalu buat ulang dengan gayamu (ATM)", "Pastikan tiap konten ada watermark, hook, isi, benefit, dan CTA", "Mulai posting rutin hari ke-7 lalu evaluasi watch time dan hook di hari ke-8"], "langkah_praktis": ["Hari 1-5: siapkan akun, riset konten viral se-niche, buat produk, dan siapkan platform jualan — belum posting dulu.", "Hari 6: optimasi tampilan profil agar terlihat kredibel dan profesional.", "Hari 7: mulai posting rutin 1-3 kali sehari; tiap konten wajib ada watermark, hook, isi, benefit, dan CTA.", "Hari 8: evaluasi lewat insight — lihat watch time dan hook mana yang paling bekerja.", "Ulangi pola konten yang performanya bagus dan hentikan yang sepi."]}, {"guid": "8b4191fa-4ee9-4976-9230-1dfe6c84d0bf", "library": "457137", "judul": "Menggabungkan Checkout Form ke Landing Page", "ringkasan": "Video ini menunjukkan cara menyatukan form checkout dari Formula.com ke dalam landing page di Scalev. Caranya: salin embed code dari menu produk di Formula, lalu tempel ke komponen HTML di landing page Scalev dan terbitkan. Setelah itu verifikasi dengan Meta Pixel Helper untuk memastikan event terpantau, lalu uji dengan mengisi form dan memastikan status pesanan berubah menjadi paid setelah pembayaran.", "poin_penting": ["Salin embed code checkout dari Formula.com", "Tempel ke komponen HTML di landing page Scalev", "Cek dengan Meta Pixel Helper: harus muncul event view dan payment info", "Uji isi form sampai status berubah paid; virtual account berubah otomatis"], "langkah_praktis": ["Di Formula.com, buka menu produk lalu salin embed code checkout-nya.", "Di Scalev, tambah komponen HTML pada landing page lalu tempel embed code tersebut dan terbitkan.", "Cek dengan Meta Pixel Helper: pastikan event view dan payment info muncul.", "Uji end-to-end: isi form, lakukan pembayaran, pastikan status pesanan berubah menjadi paid.", "Pastikan virtual account berubah otomatis mengikuti nominal pembayaran."]}, {"guid": "a147a634-4a48-463d-87ea-5705d542ac93", "library": "457137", "judul": "Membuat Landing Page dengan Scalev", "ringkasan": "Video ini memandu membuat landing page di Scalev dari daftar sampai jadi. Setelah registrasi dan verifikasi email, disarankan upgrade ke paket Light agar bisa memakai template dan halaman tak terbatas. Landing page bisa dibuat dari nol atau memakai template yang disediakan, lalu hapus form bawaan Scalev karena hanya mendukung transfer bank. Terakhir, pasang Facebook Pixel (ID plus access token) dan verifikasi dengan Meta Pixel Helper.", "poin_penting": ["Upgrade ke paket Light (sekitar Rp57 ribu) untuk template dan unlimited page", "Bisa bikin dari nol atau impor template yang disediakan", "Hapus form bawaan; form checkout-nya digabung dari Formula.com", "Pasang pixel ID dan Conversion API token lalu cek dengan Pixel Helper"], "langkah_praktis": ["Daftar akun Scalev lalu verifikasi emailmu.", "Upgrade ke paket Light (sekitar Rp57 ribu) agar bisa memakai template dan halaman tak terbatas.", "Buat landing page: dari nol atau impor template yang disediakan.", "Hapus form bawaan Scalev karena hanya mendukung transfer bank.", "Gabungkan form checkout dari Formula.com ke landing page (lihat panduan terpisah).", "Pasang pixel ID dan Conversion API token, lalu verifikasi dengan Meta Pixel Helper."]}, {"guid": "a56cb984-7b82-434d-bac2-448edccf1778", "library": "457137", "judul": "Akun Lama vs Akun Baru untuk Branding", "ringkasan": "Video ini membahas strategi memakai akun media sosial lama atau baru untuk branding. Akun lama (umur di atas sebulan, followers di bawah dua ribu, niche-nya sesuai) bisa langsung diubah jadi akun branding profesional. Akun baru wajib memakai email yang sudah berumur, seminggu pertama jangan posting dan jangan ubah ke profesional dulu, fokus saja interaksi (follow, like, komen, save) ke akun besar yang se-niche agar akun terasa natural.", "poin_penting": ["Akun lama: umur >1 bulan, <2000 followers, niche sesuai, langsung jadi akun profesional", "Akun baru: pakai email lama, 7 hari pertama jangan posting", "Minggu pertama fokus interaksi: follow 10, komen 5 yang beda-beda, like/save 10", "Satu email lama bisa dipakai menduplikasi sampai 5 akun"], "langkah_praktis": ["Punya akun lama (umur di atas sebulan, followers di bawah 2000, niche sesuai)? Langsung ubah jadi akun branding profesional.", "Untuk akun baru: pakai email yang sudah berumur agar tidak dicurigai.", "Tujuh hari pertama JANGAN posting dan JANGAN ubah ke akun profesional dulu.", "Fokus interaksi natural: follow sekitar 10, komen 5 yang beda-beda, like/save sekitar 10 ke akun besar yang se-niche.", "Satu email lama bisa dipakai untuk menduplikasi sampai 5 akun."]}, {"guid": "d5c4fcf5-dfec-4784-b2e4-beafbd8ad7cd", "library": "457137", "judul": "Membuat Checkout Form di Formula.com", "ringkasan": "Video ini memandu membuat form checkout untuk produk digital memakai Formula.com (Mengantar). Setelah daftar dan verifikasi, buat produk baru dan atur field formulirnya. Prinsipnya: jangan terlalu banyak field agar calon pembeli tidak malas mengisi, tapi jangan terlalu sedikit juga agar penjual tetap bisa follow up bila pembeli belum bayar. Field pentingnya nama, email, dan nomor WhatsApp.", "poin_penting": ["Daftar dan verifikasi akun Formula.com dulu", "Buat produk digital baru dan atur form pemesanannya", "Field seimbang: cukup untuk follow up, tidak terlalu banyak", "Wajib ada nama, email, dan nomor WhatsApp pembeli"], "langkah_praktis": ["Daftar akun Formula.com (Mengantar) lalu verifikasi emailmu.", "Buat produk digital baru dan buka pengaturan form pemesanannya.", "Atur field secukupnya: jangan terlalu banyak agar pembeli tidak malas mengisi.", "Pastikan field penting ada: nama, email, dan nomor WhatsApp untuk follow up.", "Simpan, lalu salin link atau embed form untuk dipasang di landing page."]}, {"guid": "da0b6571-58f8-455e-aa14-f2b15bcd2db1", "library": "457137", "judul": "Selamat Datang di Fast Track Produk Digital", "ringkasan": "Video pembuka ini menjelaskan gambaran program Fast Track Produk Digital selama 15 hari. Peserta akan belajar membuat produk digital dari nol: mencari ide, menentukan niche, memproduksi, sampai membangun akun media sosial yang terlihat kredibel tanpa harus tampil wajah. Ditekankan agar tidak meremehkan produk digital dan benar-benar tahu kepada siapa produk akan dijual, serta memanfaatkan sesi live bersama mentor untuk mempercepat pecah telor.", "poin_penting": ["Target 15 hari: dari nol sampai siap praktek dan pecah telor", "Belajar lengkap: ide, niche, produksi, branding sosmed faceless", "Kenali dulu target pembelimu sebelum membuat produk", "Manfaatkan 5 sesi live dengan mentor dan diskusi di Discord"], "langkah_praktis": ["Pahami target program: 15 hari dari nol sampai siap praktek dan pecah telor.", "Kenali dulu siapa target pembelimu sebelum membuat produk.", "Ikuti materi berurutan: cari ide, tentukan niche, produksi, lalu branding sosmed (bisa tanpa tampil wajah).", "Jangan meremehkan produk digital — perlakukan serius seperti bisnis sungguhan.", "Manfaatkan 5 sesi live bersama mentor dan diskusi di Discord untuk mempercepat progres."]}, {"guid": "14dfdcf3-9800-49c0-8856-6f6d09763cc3", "library": "426839", "judul": "Cara Mencairkan Dana COD dari Mengantar", "ringkasan": "Modul terakhir yang menjelaskan cara mencairkan hasil penjualan COD yang sudah terkirim sukses melalui fitur pencairan di Mengantar.", "poin_penting": ["Dana COD yang terkirim sukses bisa dicairkan", "Fitur ada di dashboard", "Data rekening harus benar"], "langkah_praktis": ["Buka dashboard Mengantar", "Cek daftar order COD berstatus terkirim sukses", "Klik fitur pencairan dana", "Pastikan data rekening benar", "Konfirmasi pencairan"]}, {"guid": "7745b286-e178-4fe6-98fa-243483970ced", "library": "426839", "judul": "Setting Gudang Online Mengantar.id untuk Aggregator", "ringkasan": "Panduan memakai gudang online mengantar.id sebagai aggregator: produk disimpan & dikirim dari gudang.", "poin_penting": ["Gudang online untuk aggregator", "Rekomendasi berdasarkan riset", "Tidak perlu packing sendiri"], "langkah_praktis": ["Daftar akun di mengantar.id", "Isi alamat penjemputan lengkap", "Masukkan nomor HP yang bisa dihubungi kurir", "Produk dikirim ke gudang, bukan ke rumah"]}, {"guid": "947ca752-dc25-4f2a-b1ea-e5bf77dbf616", "library": "426839", "judul": "Killing Offer & Plan Beriklan Versi Marketplace (Update)", "ringkasan": "Versi terbaru killing offer dan perencanaan iklan khusus marketplace dengan margin minimal Rp45 ribu.", "poin_penting": ["Margin minimal Rp45 ribu", "Dua tipe killing offer", "Update terbaru"], "langkah_praktis": ["Tentukan harga jual dengan margin minimal Rp45rb", "Pilih tipe offer: gratis ongkir atau beli 1 gratis 1", "Hitung margin bersih setelah diskon", "Sesuaikan dengan perilaku marketplace"]}, {"guid": "cb339107-13e1-475e-a9a1-da5677e9ebf1", "library": "426839", "judul": "Bikin Kampanye Iklan Pertama CTWA (Praktik Lengkap)", "ringkasan": "Praktik langkah-demi-langkah membuat kampanye iklan pertama CTWA. Prasyarat: BM, fanpage, akun whitelist.", "poin_penting": ["Prasyarat akun lengkap", "Setting campaign CTWA", "Exclude lokasi satu per satu"], "langkah_praktis": ["Siapkan BM, fanpage, akun whitelist", "Buat campaign CTWA baru", "Setting adset dan exclude lokasi", "Buat 5 ads dengan angle berbeda", "Publish dan monitor"]}];